/**
 * Conexion con la base central.
 *
 * La URL y la clave publicable se incrustan al compilar. Si el panel se
 * compilo sin ellas, se piden en pantalla y se guardan en el navegador: asi
 * el mismo archivo sirve para varios proyectos sin recompilar.
 */

import { createClient, type SupabaseClient } from '@supabase/supabase-js';

declare const __SUPABASE_URL__: string;
declare const __SUPABASE_ANON_KEY__: string;

const CLAVE_LOCAL = 'luft.admin.conexion.v1';

export interface Conexion {
  url: string;
  anonKey: string;
}

export function conexionGuardada(): Conexion | null {
  if (__SUPABASE_URL__ && __SUPABASE_ANON_KEY__) {
    return { url: __SUPABASE_URL__, anonKey: __SUPABASE_ANON_KEY__ };
  }
  try {
    const crudo = localStorage.getItem(CLAVE_LOCAL);
    if (!crudo) return null;
    const c = JSON.parse(crudo) as Conexion;
    return c.url && c.anonKey ? c : null;
  } catch {
    return null;
  }
}

export function guardarConexion(c: Conexion): void {
  localStorage.setItem(CLAVE_LOCAL, JSON.stringify(c));
}

let cliente: SupabaseClient | null = null;

export function supabase(): SupabaseClient {
  if (cliente) return cliente;
  const c = conexionGuardada();
  if (!c) throw new Error('No hay conexion configurada con la base central.');
  cliente = createClient(c.url, c.anonKey, {
    auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: false },
  });
  return cliente;
}

/** Fuerza recrear el cliente tras cambiar la conexion. */
export function reiniciarCliente(): void {
  cliente = null;
}
