function Inventario({ division, recargar }: { division: string; recargar: number }) {
  const [productos, setProductos] = useState<Producto[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busqueda, setBusqueda] = useState('');
  const [abierto, setAbierto] = useState<Producto | null>(null);
  const [editando, setEditando] = useState<Producto | null>(null);
  // Recarga propia: `recargar` llega del padre cuando nace un producto, y esta
  // se dispara al editar uno. Sumar las dos evita tener que subir el estado.
  const [trasEditar, setTrasEditar] = useState(0);
  // Los dados de baja no se ven por omision, pero tienen que poder
  // encontrarse: son la unica via para reactivar uno.
  const [verBajas, setVerBajas] = useState(false);
  const divisionCargada = useRef<string | null>(null);
  const puedeEditar = usePuedeEditar();
  const clasificaciones = useClasificaciones();
  const latido = useLatido();

  useEffect(() => {
    let vivo = true;
    // Vaciar solo al cambiar de division. Si se vaciara tambien en cada latido,
    // la tabla parpadearia a "Cargando" cada cuarenta y cinco segundos delante
    // de quien la esta leyendo. El refresco tiene que ser invisible: los
    // numeros cambian y ya.
    if (divisionCargada.current !== division) {
      setProductos(null);
      divisionCargada.current = division;
    }
    setError(null);
    supabase()
      // `admin_catalog` y no `mobile_catalog`: esta trae tambien los dados de
      // baja, con su estado. La otra es la del telefono y los excluye a
      // proposito.
      .from('admin_catalog')
      .select('*')
      .eq('business_unit', division)
      .order('name')
      .then(({ data, error: e }) => {
        if (!vivo) return;
        if (e) setError(mensajeDeError(e.message));
        else setProductos(data as Producto[]);
      });
    return () => {
      vivo = false;
    };
  }, [division, recargar, trasEditar, latido]);

  const filtrados = useMemo(() => {
    if (!productos) return [];
    const vivos = verBajas ? productos : productos.filter((p) => p.status !== 'DESCONTINUADO');
    const q = busqueda.trim().toLowerCase();
    if (!q) return vivos;
    // Tambien por clasificacion y destino: "cubrecantos" o "Etoile" son
    // exactamente como alguien busca cuando no se acuerda del codigo.
    return vivos.filter((p) =>
      [p.code, p.name, p.classification_name, p.destination]
        .some((campo) => campo?.toLowerCase().includes(q)),
    );
  }, [productos, busqueda, verBajas]);

  /**
   * Lo que falta, arriba.
   *
   * Antes la tabla venia por nombre, que es el orden de un catalogo, no el de
   * un almacen: para saber que hay que pedir habia que recorrer ochenta y
   * siete renglones leyendo la columna de la derecha. Ahora sube solo:
   * primero lo agotado, luego lo que esta bajo su minimo, y despues el resto
   * por nombre como siempre.
   *
   * Dentro de lo agotado no se ordena por cantidad -son todos cero-: se deja
   * el nombre, para que el mismo producto no cambie de sitio entre una
   * recarga y otra.
   */
  const ordenados = useMemo(() => {
    return filtrados.slice().sort((a, b) => {
      const ua = urgencia(Number(a.stock), a.min_stock);
      const ub = urgencia(Number(b.stock), b.min_stock);
      if (ua !== ub) return ua - ub;
      return a.name.localeCompare(b.name, 'es');
    });
  }, [filtrados]);

  if (error) return <Alerta>{error}</Alerta>;
  if (!productos) return <Cargando />;

  const criticos = filtrados.filter((p) => urgencia(Number(p.stock), p.min_stock) === 0).length;
  const bajos = filtrados.filter((p) => urgencia(Number(p.stock), p.min_stock) === 1).length;
  const bajas = productos.filter((p) => p.status === 'DESCONTINUADO').length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 22 }}>
      {/* La pantalla no tenia titulo, y sin el no habia jerarquia: se entraba
          directo a una tabla.

          Ahora ademas dice PARA QUE SIRVE, que es como presenta sus pantallas el
          resto de la empresa en el hub de Grupo Manantial. Alli ninguna lleva el
          titulo suelto: siempre una frase corta que aclara que es aquello y que
          pasa despues. Aqui hacia falta mas que en ninguna, porque «Inventario»
          no distingue lo que se ve —lo que HAY ahora mismo— de lo que se movio,
          que vive en otra pestana. */}
      <TituloDePagina
        sub={(
          <>
            Lo que hay ahora mismo en el almacén de {NOMBRE_DIVISION[division]}. Se
            actualiza solo con cada entrada y cada salida que registra el teléfono; lo
            escaso sube al principio de la lista.
          </>
        )}
      >
        Inventario
      </TituloDePagina>
      <span style={{ ...rotulo, display: 'block', marginTop: -14 }}>
        {filtrados.length} productos · {criticos} agotados · {bajos} bajo mínimo
      </span>

      <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', alignItems: 'center' }}>
      <input
        value={busqueda}
        onChange={(e) => setBusqueda(e.target.value)}
        placeholder="Buscar por código, nombre, clasificación o destino"
        style={{
          flex: '1 1 260px',
          border: `1px solid ${colores.linea}`,
          borderRadius: radios.md,
          // Hundido respecto al fondo: se lee como un hueco donde se escribe.
          background: colores.papel,
          color: colores.tinta,
          minHeight: 50,
          padding: '13px 18px',
          fontSize: 15,
          fontFamily: 'inherit',
        }}
      />
      {bajas > 0 && (
        <Interruptor encendido={verBajas} alCambiar={setVerBajas}>
          Ver {bajas} dados de baja
        </Interruptor>
      )}
      </div>

      {productos.length === 0 && (
        <Aviso>
          Esta división todavía no tiene productos. Los de carpintería se darán de alta desde la
          app móvil y aparecerán aquí para autorizarlos.
        </Aviso>
      )}

      {filtrados.length > 0 && (
        <Tarjeta sinRelleno style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ textAlign: 'left', borderBottom: `2px solid ${colores.linea}` }}>
                <Th>Código</Th>
                <Th>Producto</Th>
                <Th alineado="right">Existencia</Th>
                <Th>Estado</Th>
                <Th />
              </tr>
            </thead>
            <tbody>
              {ordenados.map((p) => (
                <tr
                  key={p.product_id}
                  style={{
                    borderBottom: `1px solid ${colores.linea}`,
                    // Atenuado, no tachado: sigue siendo un producto real con
                    // su historial; lo que ya no admite es capturas nuevas.
                    opacity: p.status === 'DESCONTINUADO' ? 0.45 : 1,
                  }}
                >
                  <Td>
                    <code style={{ fontSize: 13 }}>{p.code}</code>
                  </Td>
                  <Td>
                    {p.name}
                    {p.status === 'DESCONTINUADO' && (
                      <span style={{ ...rotulo, marginLeft: 10, color: colores.tintaDebil }}>
                        dado de baja
                      </span>
                    )}
                    <Leyenda
                      {...leyendaDe(clasificaciones, p.classification, p.classification_name)}
                      destino={p.destination}
                    />
                  </Td>
                  <Td alineado="right">
                    {/* Sin metal a proposito. El metal solo se sostiene desde
                        24px, y una tabla de ochenta y siete renglones con la
                        cifra a ese tamano se lee como un cartel, no como un
                        inventario. Aqui manda poder recorrer la columna: serif,
                        digitos de ancho fijo y tamano de dato. */}
                    <span
                      className="cifra"
                      style={{ fontSize: 17, fontWeight: 600, color: colores.tinta }}
                    >
                      {Number(p.stock)}
                    </span>{' '}
                    <span style={{ color: colores.tintaDebil, fontSize: 12 }}>{p.unit}</span>
                  </Td>
                  <Td>
                    <SenalStock cantidad={Number(p.stock)} minimo={p.min_stock} />
                  </Td>
                  <Td alineado="right">
                    {/* Era un boton en caja, repetido en cada renglon. Ochenta y
                        siete cajas mandan mas que los datos y ensucian la
                        pantalla; un enlace discreto hace lo mismo sin gritar. */}
                    <button
                      type="button"
                      onClick={() => setAbierto(p)}
                      style={{
                        background: 'none',
                        border: 'none',
                        padding: '6px 0',
                        color: colores.marca,
                        fontFamily: 'inherit',
                        fontSize: 12,
                        fontWeight: 600,
                        letterSpacing: '.12em',
                        textTransform: 'uppercase',
                        cursor: 'pointer',
                        whiteSpace: 'nowrap',
                      }}
                    >
                      Historial
                    </button>
                    {puedeEditar && (
                      <>
                        <span style={{ color: colores.linea, margin: '0 10px' }}>|</span>
                        <button
                          type="button"
                          onClick={() => setEditando(p)}
                          style={{
                            background: 'none',
                            border: 'none',
                            padding: '6px 0',
                            color: colores.marca,
                            fontFamily: 'inherit',
                            fontSize: 12,
                            fontWeight: 600,
                            letterSpacing: '.12em',
                            textTransform: 'uppercase',
                            cursor: 'pointer',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          Editar
                        </button>
                      </>
                    )}
                  </Td>
                </tr>
              ))}
            </tbody>
          </table>
        </Tarjeta>
      )}

      {abierto && <FichaProducto producto={abierto} alCerrar={() => setAbierto(null)} />}
      {editando && (
        <EditorProducto
          producto={editando}
          alCerrar={() => setEditando(null)}
          alGuardar={() => setTrasEditar((n) => n + 1)}
        />
      )}
    </div>
  );
}

function Th({ children, alineado }: { children?: React.ReactNode; alineado?: 'right' }) {
  return (
    <th
      style={{
        ...rotulo,
        padding: '18px 16px 12px',
        textAlign: alineado ?? 'left',
        whiteSpace: 'nowrap',
      }}
    >
      {children}
    </th>
  );
}

function Td({ children, alineado }: { children?: React.ReactNode; alineado?: 'right' }) {
  return (
    <td style={{ padding: '15px 16px', textAlign: alineado ?? 'left', fontSize: 14, verticalAlign: 'middle' }}>
      {children}
    </td>
  );
}


/**
 * Sube una imagen al almacen central y devuelve su ruta.
 *
 * El bucket es privado: lo que se guarda es la RUTA, no una direccion publica.
 * Para enseñarla se pide despues un enlace firmado y caduco, que es lo que
 * impide que una foto del almacen quede legible por cualquiera que adivine una
 * direccion.
 */
async function subirImagen(archivo: File, ruta: string): Promise<string> {
  const { error } = await supabase().storage.from('fotos').upload(ruta, archivo, {
    contentType: archivo.type || 'image/jpeg',
    upsert: true,
  });
  if (error) throw new Error(error.message);
  return ruta;
}

/**
 * Enlace temporal para VER una imagen del bucket privado.
 *
 * Caduca en una hora. Suficiente para mirarla y demasiado poco para que el
 * enlace circule por ahi con vida propia.
 */
function useImagenFirmada(ruta: string | null): string | null {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    let vivo = true;
    if (!ruta) {
      setUrl(null);
      return () => { vivo = false; };
    }
    supabase().storage.from('fotos').createSignedUrl(ruta, 3600)
      .then(({ data, error }) => {
        anotarResultado(error?.message);
        if (vivo) setUrl(data?.signedUrl ?? null);
      });
    return () => { vivo = false; };
  }, [ruta]);

  return url;
}

/**
 * La foto de referencia de un producto.
 *
 * Es contra lo que una persona compara la foto de una salida. El sistema no
 * puede hacer esa comparacion -reconocer que dos fotos son del mismo material
 * con otra luz y otro angulo necesita un modelo de vision- pero un ojo humano
 * la hace en un segundo, si tiene las dos delante.
 */
function FotoDeProducto({
  producto, alCambiar,
}: {
  producto: Producto;
  alCambiar: () => void;
}) {
  const [ruta, setRuta] = useState<string | null>(producto.image_url ?? null);
  const [subiendo, setSubiendo] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const url = useImagenFirmada(ruta);

  async function elegir(e: React.ChangeEvent<HTMLInputElement>): Promise<void> {
    const archivo = e.target.files?.[0];
    if (!archivo) return;

    setSubiendo(true);
    setError(null);
    try {
      const destino = `${producto.business_unit}/productos/${producto.product_id}.jpg`;
      await subirImagen(archivo, destino);

      const { data, error: e2 } = await supabase().rpc('app_set_product_image', {
        p_product_id: producto.product_id,
        p_url: destino,
        p_hash: null,
      });
      const r = data as { outcome: string; message?: string } | null;
      if (e2 || r?.outcome !== 'APPLIED') {
        throw new Error(e2?.message ?? r?.message ?? 'No se pudo guardar.');
      }
      setRuta(destino);
      alCambiar();
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : String(cause));
    } finally {
      setSubiendo(false);
    }
  }

  return (
    <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start' }}>
      <div
        style={{
          width: 92,
          height: 92,
          flexShrink: 0,
          borderRadius: radios.md,
          border: `1px solid ${colores.linea}`,
          background: colores.papel,
          overflow: 'hidden',
          display: 'grid',
          placeItems: 'center',
        }}
      >
        {url ? (
          <img
            src={url}
            alt={producto.name}
            style={{ width: '100%', height: '100%', objectFit: 'cover' }}
          />
        ) : (
          <span style={{ ...rotulo, color: colores.tintaDebil }}>sin foto</span>
        )}
      </div>

      <div style={{ flex: 1 }}>
        <span style={rotulo}>Fotografía del producto</span>
        <p style={{ margin: '6px 0 10px', fontSize: 13, color: colores.tintaTenue }}>
          Es contra lo que se compara la foto de cada salida. Una sola vez, y sirve para
          siempre.
        </p>
        <label
          style={{
            display: 'inline-block',
            cursor: subiendo ? 'default' : 'pointer',
            ...rotulo,
            color: colores.marca,
          }}
        >
          {subiendo ? 'Subiendo…' : url ? 'Cambiar fotografía' : 'Subir fotografía'}
          <input
            type="file"
            accept="image/*"
            disabled={subiendo}
            onChange={(e) => void elegir(e)}
            style={{ display: 'none' }}
          />
        </label>
        {error && (
          <div style={{ fontSize: 13, color: colores.rechazar, marginTop: 8 }}>{error}</div>
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Editar un producto                                                  */
/* ------------------------------------------------------------------ */

/**
 * Corregir el catalogo y cuadrar la existencia.
 *
 * Las tres operaciones van por RPC y el servidor vuelve a comprobar los
 * permisos: lo que se esconde aqui es por comodidad, no por seguridad.
 *
 * Dos cosas que esta pantalla NO hace, y no es un olvido:
 *
 *   La existencia no se escribe. Se pide el numero que hay en el anaquel y un
 *   motivo, y el servidor registra la DIFERENCIA como un movimiento de ajuste.
 *   Asi la existencia sigue siendo la suma de lo que entro y salio, y dentro de
 *   un mes se puede explicar por que cambio.
 *
 *   Un producto no se borra. Se descontinua: desaparece de busquedas y altas y
 *   su historial queda intacto. Borrarlo dejaria movimientos apuntando al vacio.
 */
function EditorProducto({
  producto, alCerrar, alGuardar,
}: {
  producto: Producto;
  alCerrar: () => void;
  alGuardar: () => void;
}) {
  const clasificaciones = useClasificaciones();
  const puedeCambiarCodigo = usePuedeCambiarCodigo();

  const [codigo, setCodigo] = useState(producto.code);
  const [nombre, setNombre] = useState(producto.name);
  const [unidad, setUnidad] = useState(producto.unit);
  const unidades = useUnidades();
  const [minimo, setMinimo] = useState(producto.min_stock === null ? '' : String(producto.min_stock));
  const [clasificacion, setClasificacion] = useState(producto.classification ?? '');
  const [destino, setDestino] = useState(producto.destination ?? '');

  const [existencia, setExistencia] = useState(String(producto.stock));
  const [motivo, setMotivo] = useState('');

  const [trabajando, setTrabajando] = useState(false);
  const [aviso, setAviso] = useState<string | null>(null);

  // Se genera al abrir, no al pulsar: un doble clic manda el mismo
  // identificador y el servidor lo reconoce como repetido en vez de ajustar
  // dos veces.
  const [txn] = useState(() => `ajuste-${crypto.randomUUID()}`);

  const cambioExistencia = Number(existencia) !== Number(producto.stock);

  async function guardar(): Promise<void> {
    setTrabajando(true);
    setAviso(null);

    const { data: d1, error: e1 } = await supabase().rpc('app_update_product', {
      p_product_id: producto.product_id,
      p_name: nombre,
      // Solo si cambio. Mandarla siempre haria que el servidor resolviera la
      // unidad en cada guardado sin motivo.
      p_unit_code: unidad !== producto.unit ? unidad : null,
      p_min_stock: minimo.trim() === '' ? null : Number(minimo),
      p_classification: clasificacion,
      p_destination: destino,
      p_notes: null,
      // Solo si de verdad cambio. Mandarlo siempre haria que el servidor
      // comprobara el permiso incluso cuando nadie toco nada.
      p_code: codigo.trim() !== producto.code && codigo.trim() !== '' ? codigo.trim() : null,
    });
    const r1 = d1 as { outcome: string; message?: string } | null;
    if (e1 || r1?.outcome !== 'APPLIED') {
      setTrabajando(false);
      setAviso(e1?.message ?? r1?.message ?? 'No se pudo guardar.');
      return;
    }

    if (cambioExistencia) {
      const { data: d2, error: e2 } = await supabase().rpc('app_adjust_stock', {
        p_client_txn_id: txn,
        p_product_id: producto.product_id,
        p_new_quantity: Number(existencia),
        p_reason: motivo,
      });
      const r2 = d2 as { outcome: string; message?: string } | null;
      if (e2 || (r2?.outcome !== 'APPLIED' && r2?.outcome !== 'DUPLICATE')) {
        setTrabajando(false);
        setAviso(
          'Los datos se guardaron, pero la existencia no: '
          + (e2?.message ?? r2?.message ?? 'error desconocido'),
        );
        return;
      }
    }

    setTrabajando(false);
    alGuardar();
    alCerrar();
  }

  /** Devuelve al catalogo un producto dado de baja. */
  async function reactivar(): Promise<void> {
    setTrabajando(true);
    const { data, error } = await supabase().rpc('app_set_product_status', {
      p_product_id: producto.product_id,
      p_status: 'ACTIVO',
      p_reason: 'Reactivado desde el panel',
    });
    const r = data as { outcome: string; message?: string } | null;
    setTrabajando(false);
    if (error || r?.outcome !== 'APPLIED') {
      setAviso(mensajeDeError(error?.message) ?? r?.message ?? 'No se pudo reactivar.');
      return;
    }
    alGuardar();
    alCerrar();
  }

  async function descontinuar(): Promise<void> {
    const razon = window.prompt(
      'El producto deja de aparecer en busquedas y altas. Su historial se conserva.\n\nMotivo de la baja:',
    );
    if (razon === null) return;

    setTrabajando(true);
    const { data, error } = await supabase().rpc('app_set_product_status', {
      p_product_id: producto.product_id,
      p_status: 'DESCONTINUADO',
      p_reason: razon,
    });
    const r = data as { outcome: string; message?: string } | null;
    setTrabajando(false);
    if (error || r?.outcome !== 'APPLIED') {
      setAviso(mensajeDeError(error?.message) ?? r?.message ?? 'No se pudo dar de baja.');
      return;
    }
    alGuardar();
    alCerrar();
  }

  return (
    <div
      onClick={alCerrar}
      style={{
        position: 'fixed', inset: 0, background: 'rgba(10,8,6,.72)',
        backdropFilter: 'blur(3px)', WebkitBackdropFilter: 'blur(3px)',
        display: 'grid', placeItems: 'center', padding: 24, zIndex: 10,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: colores.superficie, borderRadius: radios.lg,
          border: `1px solid ${colores.linea}`, boxShadow: sombras.flotante,
          width: 'min(560px, 100%)', maxHeight: '88vh', overflowY: 'auto',
        }}
      >
        <div className="filete-metal" />
        <div style={{ padding: 28, display: 'flex', flexDirection: 'column', gap: 20 }}>
          <div>
            <span style={rotulo}>{producto.code}</span>
            <h2 style={{ margin: '2px 0 0' }}>Editar producto</h2>
          </div>

          {puedeCambiarCodigo && (
            <Campo
              etiqueta="Código"
              valor={codigo}
              alCambiar={setCodigo}
              // El codigo anterior se guarda, pero no se pregona: no aparece
              // en ninguna lista ni ficha. Solo sirve para que quien lo teclee
              // pensando que sigue vigente encuentre el producto igual.
              ayuda={
                codigo.trim() !== producto.code
                  ? 'El código anterior seguirá funcionando en los teléfonos, sin aparecer en ninguna pantalla.'
                  : 'Es lo que se teclea en el teléfono.'
              }
            />
          )}

          <FotoDeProducto producto={producto} alCambiar={alGuardar} />

          <Campo etiqueta="Nombre" valor={nombre} alCambiar={setNombre} />

          <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap' }}>
            <div style={{ flex: '1 1 130px' }}>
              <Selector
                etiqueta="Unidad"
                valor={unidad}
                alCambiar={setUnidad}
                opciones={[
                  ...(unidades.some((u) => u.code === producto.unit)
                    ? []
                    : [{ valor: producto.unit, texto: producto.unit }]),
                  ...unidades.map((u) => ({ valor: u.code, texto: `${u.code} · ${u.name}` })),
                ]}
              />
            </div>
            <div style={{ flex: '1 1 130px' }}>
              <Campo etiqueta="Minimo" valor={minimo} alCambiar={setMinimo} tipo="number" />
            </div>
            <div style={{ flex: '1 1 180px' }}>
              <Selector
                etiqueta="Clasificacion"
                valor={clasificacion}
                alCambiar={setClasificacion}
                opciones={[
                  { valor: '', texto: 'Sin clasificar' },
                  ...clasificaciones.map((c) => ({ valor: c.slug, texto: c.name })),
                ]}
              />
            </div>
          </div>

          <Campo etiqueta="Destino" valor={destino} alCambiar={setDestino} />

          <div
            style={{
              borderTop: `1px solid ${colores.linea}`,
              paddingTop: 20,
              display: 'flex',
              flexDirection: 'column',
              gap: 14,
            }}
          >
            <Campo
              etiqueta="Existencia real"
              valor={existencia}
              alCambiar={setExistencia}
              tipo="number"
              ayuda={`Ahora hay ${producto.stock} ${producto.unit}. Si escribes otro numero se registra un ajuste con la diferencia; la existencia nunca se sobrescribe.`}
            />
            {cambioExistencia && (
              <Campo
                etiqueta="Motivo del ajuste"
                valor={motivo}
                alCambiar={setMotivo}
                ayuda="Obligatorio. Es lo unico que explicara este cambio dentro de un mes."
              />
            )}
          </div>

          {/* Cambiar la unidad NO convierte las cantidades: si habia 40 y se
              pasa de piezas a metros, siguen siendo 40 y ahora significan 40
              metros. Casi siempre es lo que se quiere -se capturo bien el
              numero y mal la etiqueta, que es como se equivoco quien dio el
              alta- pero decirlo evita la duda de si el sistema convirtio algo
              por su cuenta. */}
          {unidad !== producto.unit && (
            <Aviso>
              La existencia actual de <strong>{Number(producto.stock)}</strong> pasará a leerse
              en <strong>{unidad}</strong>. El número no cambia: se corrige la etiqueta, no la
              cantidad. Si además la cantidad estaba mal, ajústela abajo.
            </Aviso>
          )}

          {aviso && <Alerta>{aviso}</Alerta>}

          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center' }}>
            <Boton
              tono="marca"
              onClick={() => void guardar()}
              disabled={
                trabajando || nombre.trim() === '' || (cambioExistencia && motivo.trim() === '')
              }
            >
              {trabajando ? 'Guardando...' : 'Guardar'}
            </Boton>
            <Boton onClick={alCerrar} disabled={trabajando}>Cancelar</Boton>
            <div style={{ flex: 1 }} />
            {producto.status === 'DESCONTINUADO' ? (
              <Boton onClick={() => void reactivar()} disabled={trabajando}>
                Reactivar
              </Boton>
            ) : (
              <Boton tono="rechazar" onClick={() => void descontinuar()} disabled={trabajando}>
                Dar de baja
              </Boton>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Ficha e historial                                                   */
/* ------------------------------------------------------------------ */

function FichaProducto({ producto, alCerrar }: { producto: Producto; alCerrar: () => void }) {
  const [movs, setMovs] = useState<Movimiento[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const clasificaciones = useClasificaciones();

  useEffect(() => {
    let vivo = true;
    supabase()
      .from('inventory_movements')
      .select(
        'id, movement_type, quantity, balance_after, occurred_at, raw_date, notes, responsible_name, projects(name), app_users!inventory_movements_created_by_fkey(full_name)',
      )
      .eq('product_id', producto.product_id)
      .order('occurred_at', { ascending: false, nullsFirst: false })
      .limit(200)
      .then(({ data, error: e }) => {
        if (!vivo) return;
        if (e) {
          setError(mensajeDeError(e.message));
          return;
        }
        setMovs(
          (data ?? []).map((m: Record<string, unknown>) => ({
            id: m['id'] as string,
            movement_type: m['movement_type'] as string,
            quantity: Number(m['quantity']),
            balance_after: Number(m['balance_after']),
            occurred_at: m['occurred_at'] as string | null,
            raw_date: m['raw_date'] as string | null,
            notes: m['notes'] as string | null,
            responsible_name: m['responsible_name'] as string | null,
            project_name: (m['projects'] as { name: string } | null)?.name ?? null,
            autor: (m['app_users'] as { full_name: string } | null)?.full_name ?? null,
          })),
        );
      });
    return () => {
      vivo = false;
    };
  }, [producto.product_id]);

  return (
    <div
      onClick={alCerrar}
      style={{
        position: 'fixed',
        inset: 0,
        // Velo calido y denso: sobre fondo oscuro un velo claro no aparta
        // nada, y la tarjeta de encima tiene que quedarse sola en la escena.
        background: 'rgba(10,8,6,.72)',
        backdropFilter: 'blur(3px)',
        WebkitBackdropFilter: 'blur(3px)',
        display: 'grid',
        placeItems: 'center',
        padding: 24,
        zIndex: 10,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: colores.superficie,
          borderRadius: radios.lg,
          boxShadow: sombras.flotante,
          width: 'min(720px, 100%)',
          maxHeight: '85vh',
          overflow: 'auto',
          padding: 24,
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 16 }}>
          <div>
            <code style={{ fontSize: 13, color: colores.tintaTenue }}>{producto.code}</code>
            <h2 style={{ margin: '2px 0 0' }}>{producto.name}</h2>
            <Leyenda
              {...leyendaDe(clasificaciones, producto.classification, producto.classification_name)}
              destino={producto.destination}
            />
            <div style={{ marginTop: 6, fontSize: 14 }}>
              <span className="num" style={{ fontWeight: 700, fontSize: 18 }}>
                {Number(producto.stock)}
              </span>{' '}
              {producto.unit} · <SenalStock cantidad={Number(producto.stock)} minimo={producto.min_stock} />
            </div>
          </div>
          <Boton onClick={alCerrar}>Cerrar</Boton>
        </div>

        <h3 style={{ fontSize: 14, marginTop: 24, marginBottom: 8 }}>Historial</h3>
        {error && <Alerta>{error}</Alerta>}
        {!movs && !error && <Cargando />}
        {movs && movs.length === 0 && (
          <p style={{ color: colores.tintaTenue, fontSize: 14 }}>Sin movimientos registrados.</p>
        )}
        {movs && movs.length > 0 && (
          // Con su propio barrido lateral. Las otras cuatro tablas del panel lo
          // tienen y esta no: en una pantalla estrecha empujaba la PAGINA
          // entera de lado, y entonces se barre el encabezado y las pestanas
          // junto con los datos.
          <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: `2px solid ${colores.linea}` }}>
                <Th>Fecha</Th>
                <Th>Tipo</Th>
                <Th alineado="right">Cantidad</Th>
                <Th alineado="right">Quedó</Th>
                <Th>Obra</Th>
                <Th>Quién</Th>
              </tr>
            </thead>
            <tbody>
              {movs.map((m) => (
                <tr key={m.id} style={{ borderBottom: `1px solid ${colores.linea}` }}>
                  <Td>{fecha(m)}</Td>
                  <Td>{NOMBRE_TIPO[m.movement_type] ?? m.movement_type}</Td>
                  <Td alineado="right">
                    <span
                      className="num"
                      style={{
                        fontWeight: 600,
                        color: esEntrada(m.movement_type) ? colores.aprobar : colores.rechazar,
                      }}
                    >
                      {esEntrada(m.movement_type) ? '+' : '−'}
                      {Math.abs(m.quantity)}
                    </span>
                  </Td>
                  <Td alineado="right">
                    <span className="num">{m.balance_after}</span>
                  </Td>
                  <Td>{m.project_name ?? '—'}</Td>
                  <Td>{m.autor ?? m.responsible_name ?? '—'}</Td>
                </tr>
              ))}
            </tbody>
          </table>
          </div>
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Pendientes (aun sin circuito en la base)                            */
/* ------------------------------------------------------------------ */

interface Propuesta {
  id: string;
  code: string;
  name: string;
  unit_code: string | null;
  notes: string | null;
  proposed_at: string;
  business_unit_id: string;
  division: string;
  autor: string | null;
  classification: string | null;
  destination: string | null;
  /** La existencia contada en la nave. Nula = el producto arranca en 0. */
  initial_quantity: number | null;
}

/**
 * La cantidad escrita, ya en numero. Nula = no meter existencia.
 *
 * Acepta coma decimal porque el panel se usa con teclado de espanol y "1,5"
 * es lo que sale al teclear. Si no es un numero utilizable devuelve nulo: es
 * el propio servidor quien rechaza lo que no cuadra, y mandar `NaN` produciria
 * un error de base de datos en vez de un mensaje que se pueda leer.
 */
function cantidadDeTexto(texto: string): number | null {
  const limpio = texto.trim().replace(',', '.');
  if (limpio === '') return null;
  const n = Number(limpio);
  return Number.isFinite(n) && n >= 0 ? n : null;
}

/** Lo que el revisor escribe en una propuesta antes de aprobarla. */
interface Etiqueta {
  clasificacion: string;
  destino: string;
  /**
   * La unidad, que quien revisa puede corregir.
   *
   * En el telefono se escribe a mano, y de ahi salen cosas como "PZA 1" cuando
   * el catalogo tiene "PZA". Antes eso dejaba la propuesta atascada: no habia
   * donde arreglarlo, y las unicas salidas eran rechazar el producto —haciendo
   * repetir la captura por una letra— o dar de alta una unidad inventada que
   * ensuciaria el catalogo para siempre.
   */
  unidad: string;

  /**
   * La existencia que va a entrar al aprobar, corregible.
   *
   * Cadena y no numero: el campo esta a medio escribir mientras se teclea, y
   * un numero obligaria a decidir que es "12," o "" en cada pulsacion. Se
   * convierte al enviar, que es el unico momento en que importa.
   *
   * Corregible por el mismo motivo que la unidad: quien aprueba pudo contar
   * otra cosa, o la almacenista pudo escribir 100 donde queria 10. Vaciarla
   * significa aprobar sin meter existencia.
   */
  cantidad: string;
}

/* ------------------------------------------------------------------ */
/* Salidas por autorizar                                               */
/* ------------------------------------------------------------------ */

type Salida = {
  movement_id: string;
  division: string;
  product_code: string;
  product_name: string;
  quantity: number;
  unit_code: string | null;
  project_name: string | null;
  created_by_name: string | null;
  occurred_at: string;
  notes: string | null;
  balance_after: number | null;
};

/**
 * La bandeja donde un supervisor decide si el material sale de verdad.
 *
 * Todo lo que hace falta para decidir esta en la fila: que producto, cuanto,
 * a que obra, quien lo saco y con cuanto queda el estante. Nada de abrir una
 * ficha aparte —quien revisa esto suele tener a alguien esperando enfrente.
 */
function SalidasPorAutorizar() {
  const latido = useLatido();
  const [filas, setFilas] = useState<Salida[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [trabajando, setTrabajando] = useState<string | null>(null);
  const [resultado, setResultado] = useState<string | null>(null);

  async function cargar() {
    const { data, error: e } = await supabase()
      .from('movement_authorization_status')
      .select(
        'movement_id, division, product_code, product_name, quantity, unit_code, ' +
          'project_name, created_by_name, occurred_at, notes, balance_after',
      )
      .eq('status', 'PENDIENTE')
      .order('occurred_at', { ascending: true });

    if (e) {
      setError(mensajeDeError(e.message));
      return;
    }
    setError(null);
    setFilas((data ?? []) as unknown as Salida[]);
  }

  useEffect(() => {
    // A media autorizacion no se recarga: la lista cambiaria bajo el dedo de
    // quien tiene a alguien esperando enfrente.
    if (trabajando) return;
    void cargar();
  }, [latido, trabajando]);

  async function decidir(fila: Salida, autorizar: boolean) {
    let motivo: string | null = null;

    if (!autorizar) {
      // Un rechazo sin motivo deja al almacenista sin saber que hizo mal y al
      // historial sin explicar por que volvio el material. La base lo exige;
      // aqui se pide antes para no gastarle el viaje al servidor.
      motivo = window.prompt(
        `¿Por qué se rechaza esta salida?\n\n${fila.quantity} ${fila.unit_code ?? ''} de ${fila.product_name}`,
      );
      if (motivo === null) return;
      if (motivo.trim() === '') {
        setResultado('Un rechazo necesita motivo. No se hizo nada.');
        return;
      }
    }

    setTrabajando(fila.movement_id);
    setResultado(null);

    const { error: e } = await supabase().rpc('app_review_exit', {
      p_movement_id: fila.movement_id,
      p_approve: autorizar,
      p_reason: motivo,
    });

    setTrabajando(null);

    if (e) {
      setResultado(mensajeDeError(e.message));
      return;
    }

    setResultado(
      autorizar
        ? `Autorizada la salida de ${fila.quantity} ${fila.unit_code ?? ''} de ${fila.product_name}.`
        : `Rechazada. El material volvió al inventario: ${fila.quantity} ${fila.unit_code ?? ''} de ${fila.product_name}.`,
    );
    await cargar();
  }

  if (error) return <Alerta>{error}</Alerta>;
  if (filas === null) return <Cargando texto="Buscando salidas pendientes…" />;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 22 }}>
      {/* Sin frase explicativa a proposito, aunque el resto de pantallas la
          lleve: justo debajo va el aviso, y dice lo mismo con mas peso del que
          tendria en gris pequeno. Repetirlo arriba solo ensena a saltarselo. */}
      <TituloDePagina>Salidas por autorizar</TituloDePagina>
      <span style={{ ...rotulo, display: 'block', marginTop: -14 }}>
        {filas.length === 0 ? 'nada pendiente' : `${filas.length} esperando`}
      </span>

      <Aviso>
        Mientras una salida esté aquí, el material <strong>ya salió físicamente</strong> y la
        existencia ya lo refleja. Autorizar la deja firme; rechazarla devuelve la cantidad al
        inventario y queda registrado quién dijo que no.
      </Aviso>

      {resultado && <Aviso>{resultado}</Aviso>}

      {filas.length === 0 ? (
        <Tarjeta>
          <div style={{ textAlign: 'center', padding: 28 }}>
            <div style={{ fontSize: 32, marginBottom: 8 }}>✓</div>
            <div style={{ fontSize: 17, fontWeight: 600 }}>No hay salidas esperando</div>
            <div style={{ fontSize: 14, color: colores.tintaTenue, marginTop: 4 }}>
              Todo lo que ha salido del almacén está revisado.
            </div>
          </div>
        </Tarjeta>
      ) : (
        filas.map((f) => (
          <Tarjeta key={f.movement_id}>
            <div
              style={{
                display: 'flex',
                gap: 20,
                flexWrap: 'wrap',
                alignItems: 'flex-start',
              }}
            >
              <div style={{ flex: '1 1 320px', minWidth: 0 }}>
                <div style={{ fontSize: 17, fontWeight: 600 }}>{f.product_name}</div>
                <div
                  className="num"
                  style={{ fontSize: 13, color: colores.tintaTenue, marginTop: 2 }}
                >
                  {f.product_code} · {f.division}
                </div>

                <div style={{ marginTop: 12, display: 'flex', gap: 24, flexWrap: 'wrap' }}>
                  <Dato etiqueta="Cantidad">
                    <span className="num" style={{ fontSize: 19, fontWeight: 600 }}>
                      {f.quantity} {f.unit_code ?? ''}
                    </span>
                  </Dato>
                  <Dato etiqueta="Queda">
                    <span
                      className="num"
                      style={{
                        fontSize: 19,
                        fontWeight: 600,
                        color:
                          (f.balance_after ?? 0) <= 0 ? colores.rechazar : colores.tinta,
                      }}
                    >
                      {f.balance_after ?? '—'}
                    </span>
                  </Dato>
                  <Dato etiqueta="Obra">{f.project_name ?? 'Sin obra'}</Dato>
                  <Dato etiqueta="La sacó">{f.created_by_name ?? 'Desconocido'}</Dato>
                  <Dato etiqueta="Cuándo">
                    {new Date(f.occurred_at).toLocaleString('es-MX', {
                      day: '2-digit',
                      month: 'short',
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </Dato>
                </div>

                {f.notes && (
                  <div style={{ marginTop: 10, fontSize: 14, color: colores.tintaTenue }}>
                    {f.notes}
                  </div>
                )}
              </div>

              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                <Boton
                  tono="aprobar"
                  disabled={trabajando !== null}
                  onClick={() => void decidir(f, true)}
                >
                  {trabajando === f.movement_id ? '…' : 'Autorizar'}
                </Boton>
                <Boton
                  tono="rechazar"
                  disabled={trabajando !== null}
                  onClick={() => void decidir(f, false)}
                >
                  Rechazar
                </Boton>
              </div>
            </div>
          </Tarjeta>
        ))
      )}
    </div>
  );
}

function Dato({ etiqueta, children }: { etiqueta: string; children: React.ReactNode }) {
  return (
    <div>
      <div
        style={{
          fontSize: 11,
          fontWeight: 600,
          letterSpacing: '.06em',
          color: colores.tintaDebil,
          textTransform: 'uppercase',
        }}
      >
        {etiqueta}
      </div>
      <div style={{ fontSize: 14, marginTop: 2 }}>{children}</div>
    </div>
  );
}

function ProductosPorAprobar({ alAprobar }: { alAprobar: () => void }) {
  const latido = useLatido();
  const [filas, setFilas] = useState<Propuesta[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [trabajando, setTrabajando] = useState<string | null>(null);
  const [resultado, setResultado] = useState<string | null>(null);
  const clasificaciones = useClasificaciones();
  const unidades = useUnidades();

  /**
   * Clasificacion y destino que el revisor pone antes de firmar.
   *
   * Se piden AQUI y no en el movil a proposito: quien captura en la nave tiene
   * el material en la mano y sabe como se llama; quien aprueba conoce el
   * catalogo entero y sabe donde encaja. Pedirle la etiqueta al almacenista es
   * pedirle una decision que no le toca, y acaba con todo marcado como
   * "insumos" porque era la primera opcion de la lista.
   *
   * Ninguna de las dos es obligatoria. Un producto sin clasificar se clasifica
   * despues; parar un alta por una etiqueta seria parar el almacen por un
   * adorno.
   */
  const [etiquetas, setEtiquetas] = useState<Record<string, Etiqueta>>({});

  function etiquetaDe(p: Propuesta): Etiqueta {
    return (
      etiquetas[p.id] ?? {
        clasificacion: p.classification ?? '',
        destino: p.destination ?? '',
        unidad: p.unit_code ?? '',
        cantidad: p.initial_quantity === null ? '' : String(p.initial_quantity),
      }
    );
  }

  function cambiarEtiqueta(p: Propuesta, cambio: Partial<Etiqueta>) {
    setEtiquetas((previo) => ({ ...previo, [p.id]: { ...etiquetaDe(p), ...cambio } }));
  }

  /**
   * Seleccion para aprobar en bloque.
   *
   * Existe porque cargar el catalogo de carpinteria son cientos de altas, y
   * aprobarlas de una en una convierte el control en un peaje que nadie
   * quiere pagar —y un control que estorba acaba desactivado.
   *
   * En bloque SOLO se aprueba. Rechazar sigue siendo de uno en uno, porque
   * cada rechazo necesita su motivo: sin el, el almacenista no sabe que hizo
   * mal y vuelve a proponer lo mismo.
   */
  const [marcados, setMarcados] = useState<Set<string>>(new Set());

  function alternar(id: string) {
    setMarcados((previo) => {
      const siguiente = new Set(previo);
      if (siguiente.has(id)) siguiente.delete(id);
      else siguiente.add(id);
      return siguiente;
    });
  }

  async function aprobarMarcados(lista: Propuesta[]) {
    const seleccionadas = lista.filter((p) => marcados.has(p.id));
    if (seleccionadas.length === 0) return;

    setTrabajando('lote');
    setResultado(null);

    // UN viaje para todo el lote.
    //
    // Antes era uno por propuesta. En la base cada aprobacion tarda decimas de
    // milisegundo, pero cada viaje a Supabase cuesta unos 130 ms: doscientas
    // altas —que es lo que es cargar el catalogo de carpinteria— eran 26
    // segundos de pantalla bloqueada, de los que 25.8 eran cable.
    //
    // Lo que NO cambia: el servidor sigue pasando cada propuesta por
    // `app_review_proposal`, la misma funcion de una en una, con las mismas
    // comprobaciones. El atajo es para el cable, no para las reglas. Y cada
    // una va en su propia subtransaccion, asi que una que falle no tumba las
    // demas.
    const { data, error: e } = await supabase().rpc('app_review_proposals', {
      p_items: seleccionadas.map((propuesta) => {
        const etiqueta = etiquetaDe(propuesta);
        return {
          id: propuesta.id,
          code: propuesta.code,
          approve: true,
          classification: etiqueta.clasificacion || null,
          destination: etiqueta.destino.trim() || null,
          unit_code: etiqueta.unidad.trim() || null,
          initial_quantity: cantidadDeTexto(etiqueta.cantidad),
        };
      }),
    });

    // Se mira propuesta por propuesta. La funcion contesta con un motivo en
    // vez de reventar —codigo ya existente, unidad desconocida—, y sin
    // mirarlos un lote de veinte saldria como "20 aprobados" con la mitad sin
    // crear.
    const resultados =
      (data as { resultados?: { code: string; outcome: string; message: string }[] } | null)
        ?.resultados ?? [];
    const fallos = e
      ? [e.message]
      : resultados
        .filter((r) => r.outcome !== 'APPROVED')
        .map((r) => `${r.code}: ${r.message}`);
    const bien = e ? 0 : resultados.filter((r) => r.outcome === 'APPROVED').length;

    setTrabajando(null);
    setMarcados(new Set());
    setResultado(
      fallos.length === 0
        ? `${bien} producto(s) aprobados.`
        : `${bien} aprobados. ${fallos.length} sin aprobar — ${fallos.slice(0, 3).join(' · ')}` +
          (fallos.length > 3 ? ` y ${fallos.length - 3} más.` : ''),
    );
    if (bien > 0) alAprobar();
    await cargar();
  }

  async function cargar() {
    const { data, error: e } = await supabase()
      .from('product_proposals')
      .select('id, code, name, unit_code, notes, classification, destination, initial_quantity, proposed_at, business_unit_id, business_units(slug), app_users!product_proposals_proposed_by_fkey(full_name)')
      .eq('status', 'PENDIENTE')
      .order('proposed_at', { ascending: true });

    if (e) {
      setError(mensajeDeError(e.message));
      return;
    }
    setFilas(
      (data ?? []).map((p: Record<string, unknown>) => ({
        id: p['id'] as string,
        code: p['code'] as string,
        name: p['name'] as string,
        unit_code: p['unit_code'] as string | null,
        initial_quantity: p['initial_quantity'] === null || p['initial_quantity'] === undefined
          ? null
          : Number(p['initial_quantity']),
        notes: p['notes'] as string | null,
        classification: p['classification'] as string | null,
        destination: p['destination'] as string | null,
        proposed_at: p['proposed_at'] as string,
        business_unit_id: p['business_unit_id'] as string,
        division: (p['business_units'] as { slug: string } | null)?.slug ?? '',
        autor: (p['app_users'] as { full_name: string } | null)?.full_name ?? null,
      })),
    );
  }

  useEffect(() => {
    if (trabajando) return;
    void cargar();
  }, [latido, trabajando]);

  async function revisar(p: Propuesta, aprobar: boolean) {
    // Rechazar sin motivo deja a quien lo propuso sin saber que corregir.
    let motivo: string | null = null;
    if (!aprobar) {
      motivo = window.prompt(`¿Por qué se rechaza "${p.name}"?`);
      if (motivo === null) return;
      if (!motivo.trim()) {
        setResultado('El rechazo necesita un motivo: quien lo propuso tiene que saber qué corregir.');
        return;
      }
    }

    const etiqueta = etiquetaDe(p);

    setTrabajando(p.id);
    setResultado(null);
    const { data, error: e } = await supabase().rpc('app_review_proposal', {
      p_proposal_id: p.id,
      p_approve: aprobar,
      p_notes: motivo,
      p_classification: aprobar ? etiqueta.clasificacion || null : null,
      p_destination: aprobar ? etiqueta.destino.trim() || null : null,
      p_unit_code: aprobar ? etiqueta.unidad.trim() || null : null,
      p_initial_quantity: aprobar ? cantidadDeTexto(etiqueta.cantidad) : null,
    });
    setTrabajando(null);

    if (e) {
      setResultado(mensajeDeError(e.message));
      return;
    }
    const r = data as { outcome: string; message: string };
    setResultado(mensajeDeError(r.message));
    if (r.outcome === 'APPROVED') alAprobar();
    await cargar();
  }

  if (error) return <Alerta>{error}</Alerta>;
  if (!filas) return <Cargando />;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <TituloDePagina sub={<>Capturados desde la app. Todavía no existen en el inventario y no admiten movimientos
          hasta que se autoricen. Aquí se les pone la clasificación y el destino antes de firmar
          —y se revisa la <strong>existencia contada en la nave</strong>: al aprobar entra como
          ENTRADA, fechada el día en que se capturó, y el material queda en el inventario sin que
          nadie tenga que volver a apuntarlo.</>}>
        Productos por aprobar
      </TituloDePagina>

      {resultado && <Aviso>{resultado}</Aviso>}

      {filas.length === 0 && (
        <Tarjeta>
          <p style={{ margin: 0, color: colores.tintaTenue }}>Nada pendiente de aprobar.</p>
        </Tarjeta>
      )}

      {/* Barra de seleccion. Aparece solo cuando hay algo que aprobar en
          bloque: una barra vacia permanente es ruido. */}
      {filas.length > 0 && (
        <div
          style={{
            display: 'flex',
            gap: 12,
            alignItems: 'center',
            flexWrap: 'wrap',
            padding: '12px 16px',
            background: colores.superficie,
            borderRadius: radios.md,
            boxShadow: sombras.suave,
          }}
        >
          <label style={{ display: 'flex', gap: 8, alignItems: 'center', fontSize: 14 }}>
            <input
              type="checkbox"
              checked={marcados.size === filas.length && filas.length > 0}
              onChange={(e) =>
                setMarcados(e.target.checked ? new Set(filas.map((f) => f.id)) : new Set())
              }
            />
            Seleccionar todo ({filas.length})
          </label>

          <span style={{ flex: 1 }} />

          <span style={{ fontSize: 14, color: colores.tintaTenue }}>
            {marcados.size} seleccionado{marcados.size === 1 ? '' : 's'}
          </span>

          <Boton
            tono="aprobar"
            disabled={marcados.size === 0 || trabajando !== null}
            onClick={() => void aprobarMarcados(filas)}
          >
            {trabajando === 'lote' ? 'Aprobando…' : `Aprobar ${marcados.size || ''}`.trim()}
          </Boton>
        </div>
      )}

      {filas.map((p) => (
        <Tarjeta key={p.id}>
          <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', alignItems: 'flex-start' }}>
            <input
              type="checkbox"
              checked={marcados.has(p.id)}
              onChange={() => alternar(p.id)}
              style={{ marginTop: 4, width: 18, height: 18 }}
              aria-label={`Seleccionar ${p.code}`}
            />
            <div style={{ flex: '1 1 300px' }}>
              <code style={{ fontSize: 13, color: colores.tintaTenue }}>{p.code}</code>
              <div style={{ fontSize: 17, fontWeight: 600 }}>{p.name}</div>
              {/* La leyenda tal como quedara debajo del nombre una vez
                  aprobado. Cambia mientras se elige, para que no haya que
                  aprobar a ciegas y comprobar despues en el inventario. */}
              <Leyenda
                {...leyendaDe(clasificaciones, etiquetaDe(p).clasificacion || null)}
                destino={etiquetaDe(p).destino.trim() || null}
              />
              <div style={{ fontSize: 13, color: colores.tintaTenue, marginTop: 6 }}>
                {NOMBRE_DIVISION[p.division] ?? p.division} · unidad {p.unit_code ?? 'PZA'} ·{' '}
                {p.initial_quantity === null ? (
                  'sin existencia'
                ) : (
                  <strong style={{ color: colores.tinta }}>
                    {p.initial_quantity} {p.unit_code ?? 'PZA'} contadas
                  </strong>
                )}{' '}
                ·{' '}
                {p.autor ?? 'sin identificar'} ·{' '}
                {new Date(p.proposed_at).toLocaleString('es-MX', {
                  day: '2-digit',
                  month: 'short',
                  hour: '2-digit',
                  minute: '2-digit',
                })}
              </div>
              {p.notes && (
                <div style={{ fontSize: 14, marginTop: 8 }}>{p.notes}</div>
              )}

              <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', marginTop: 12 }}>
                <div style={{ flex: '1 1 180px' }}>
                  <Selector
                    etiqueta="Clasificación"
                    valor={etiquetaDe(p).clasificacion}
                    alCambiar={(v) => cambiarEtiqueta(p, { clasificacion: v })}
                    opciones={[
                      { valor: '', texto: 'Sin clasificar' },
                      ...clasificaciones.map((c) => ({ valor: c.slug, texto: c.name })),
                    ]}
                  />
                </div>
                <div style={{ flex: '1 1 150px' }}>
                  {/* La unidad se escribe a mano en el telefono, y de ahi salen
                      cosas como "PZA 1". Aqui se elige de la lista real: es la
                      diferencia entre corregir una errata y quedarse
                      atascado. */}
                  <Selector
                    etiqueta="Unidad"
                    valor={etiquetaDe(p).unidad}
                    alCambiar={(v) => cambiarEtiqueta(p, { unidad: v })}
                    opciones={[
                      ...(unidades.some((u) => u.code === etiquetaDe(p).unidad)
                        ? []
                        : [{
                            valor: etiquetaDe(p).unidad,
                            texto: `${etiquetaDe(p).unidad} — no existe`,
                          }]),
                      ...unidades.map((u) => ({ valor: u.code, texto: `${u.code} · ${u.name}` })),
                    ]}
                  />
                </div>
                {/* La existencia que entra al aprobar.
                    Viene contada de la nave, por quien tenia el material
                    delante. Se puede corregir —quien aprueba pudo contar otra
                    cosa— y se puede vaciar, que significa dar de alta el
                    producto sin meter nada. */}
                <div style={{ flex: '1 1 150px' }}>
                  <Campo
                    etiqueta="Existencia inicial"
                    valor={etiquetaDe(p).cantidad}
                    alCambiar={(v) => cambiarEtiqueta(p, { cantidad: v })}
                    ayuda={
                      etiquetaDe(p).cantidad.trim() === ''
                        ? 'Vacío: arranca en 0.'
                        : `Entra como ENTRADA de ${etiquetaDe(p).cantidad.trim()} `
                          + `${etiquetaDe(p).unidad || 'PZA'}.`
                    }
                  />
                </div>
                <div style={{ flex: '2 1 240px' }}>
                  <Campo
                    etiqueta="Destino del material"
                    valor={etiquetaDe(p).destino}
                    alCambiar={(v) => cambiarEtiqueta(p, { destino: v })}
                  />
                </div>
              </div>
            </div>
            <div style={{ display: 'flex', gap: 8 }}>
              <Boton
                tono="rechazar"
                disabled={trabajando === p.id}
                onClick={() => void revisar(p, false)}
              >
                Rechazar
              </Boton>
              <Boton
                tono="aprobar"
                disabled={trabajando === p.id}
                onClick={() => void revisar(p, true)}
              >
                {trabajando === p.id ? 'Guardando…' : 'Aprobar'}
              </Boton>
            </div>
          </div>
        </Tarjeta>
      ))}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Alta directa desde el panel                                         */
/* ------------------------------------------------------------------ */

/**
 * Dar de alta un producto sin pasar por el movil.
 *
 * Hasta ahora la unica puerta era proponer desde la app y aprobar aqui. Sirve
 * para el almacenista, que tiene el material delante; no sirve para quien esta
 * sentado en el panel cargando un catalogo de proveedor.
 *
 * Lo que NO hace: poner existencia. El producto nace en cero y la cantidad
 * entra por su movimiento, con fecha y con autor. Un campo de "existencia
 * inicial" aqui seria inventar una entrada que nadie hizo, y el historial
 * dejaria de cuadrar desde el primer dia.
 */
interface Obra {
  id: string;
  code: string;
  name: string;
  status: string;
}

/**
 * Si esta persona puede tocar el catalogo de obras.
 *
 * `product.approve`: administracion y supervision. Los dos almacenistas
 * quedan fuera a proposito —ellos ELIGEN la obra en el telefono, no la
 * escriben— y es la misma linea que separa a quien corrige el catalogo de
 * quien registra movimientos.
 *
 * Ante un error responde que NO, como `usePuedeEditar`: esconder botones que
 * iban a fallar es mejor que ensenarlos. La decision de verdad no es esta; el
 * servidor vuelve a comprobar el permiso en cada RPC.
 */
/**
 * Cuantos esperan. No sale cuando no hay ninguno.
 *
 * Un cero en un circulo sigue siendo una marca que pide atencion, y una que
 * esta siempre encendida deja de significar nada —es el mismo motivo por el
 * que el aviso de sincronizacion del telefono solo aparece cuando hay algo que
 * decir.
 */
function Cuantas({ n }: { n: number }) {
  if (n === 0) return null;
  return (
    <span
      aria-label={`${n} pendientes`}
      style={{
        display: 'inline-block',
        minWidth: 20,
        marginLeft: 6,
        padding: '1px 6px',
        borderRadius: 999,
        // `rechazar` y no un rojo suelto: es el color que este panel ya usa
        // para "esto pide una decision", y esta calibrado contra el fondo
        // espresso. Un #FF0000 encima de este fondo vibra y se lee peor.
        background: colores.rechazar,
        color: colores.papel,
        fontSize: 12,
        fontWeight: 700,
        lineHeight: '17px',
        textAlign: 'center',
        fontVariantNumeric: 'tabular-nums',
      }}
    >
      {n}
    </span>
  );
}

/**
 * El saludo de quien acaba de entrar, si tiene uno.
 *
 * Sale de `app_users.welcome_message` —un dato de la persona— y no de una
 * comparacion de correos en el codigo. El panel solo pregunta "¿tengo saludo?";
 * quien decide es la base. Cambiarlo o quitarlo no obliga a recompilar nada, y
 * el correo de nadie viaja en el paquete que se descarga cualquiera.
 *
 * Se ensena UNA vez por sesion del navegador. Un cartel que reaparece en cada
 * recarga deja de ser una bienvenida y pasa a ser un estorbo.
 */
const YA_SALUDADO = 'luft.saludado.v1';

function useSaludo(authUserId: string | null): { texto: string; nombre: string } | null {
  const [saludo, setSaludo] = useState<{ texto: string; nombre: string } | null>(null);

  useEffect(() => {
    let vivo = true;
    if (!authUserId) return undefined;
    if (sessionStorage.getItem(YA_SALUDADO) === '1') return undefined;

    supabase()
      .from('app_users')
      .select('full_name, welcome_message')
      // Se filtra por QUIEN ES, no se confia en que la seguridad por filas
      // recorte el resultado.
      //
      // Es un fallo que estuvo escrito y habria salido a la cara: quien
      // administra usuarios PUEDE leer las filas de los demas (0007), asi que
      // pedir "la primera fila que tenga saludo" le habria ensenado a la
      // administracion el saludo del CEO. Apoyarse en RLS para acotar un
      // resultado funciona solo mientras nadie tenga mas permisos de los
      // previstos, y la administracion siempre los tiene.
      .eq('auth_user_id', authUserId)
      .not('welcome_message', 'is', null)
      .limit(1)
      .then(({ data, error }) => {
        if (!vivo || error || !data || data.length === 0) return;
        const fila = data[0] as { full_name: string; welcome_message: string };
        setSaludo({ texto: fila.welcome_message, nombre: fila.full_name });
      });

    return () => {
      vivo = false;
    };
  }, [authUserId]);

  return saludo;
}

/**
 * La bienvenida.
 *
 * Ocupa la pantalla entera y se quita al pulsar. No se cierra sola con un
 * temporizador: si a alguien le hablan justo cuando entra, un cartel que se va
 * a los tres segundos no se lee nunca.
 */
function Bienvenida({ texto, nombre, alCerrar }: {
  texto: string;
  nombre: string;
  alCerrar: () => void;
}) {
  return (
    <div
      role="dialog"
      aria-label={texto}
      onClick={alCerrar}
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 50,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 18,
        background: colores.papel,
        cursor: 'pointer',
        textAlign: 'center',
        padding: 24,
      }}
    >
      <Firma ancho={120} />
      <div
        style={{
          fontSize: 'clamp(34px, 9vw, 76px)',
          fontWeight: 800,
          letterSpacing: -1.5,
          lineHeight: 1.02,
          color: colores.marca,
          textWrap: 'balance',
        }}
      >
        {texto}
      </div>
      <div style={{ fontSize: 17, color: colores.tinta }}>{nombre}</div>
      <div style={{ fontSize: 13, color: colores.tintaTenue, marginTop: 10 }}>
        Toque en cualquier parte para entrar
      </div>
    </div>
  );
}

interface Pendientes {
  salidas: number;
  productos: number;
  rechazos_sin_ver: number;
}

/**
 * Lo que espera a alguien, para poder ensenarlo en la pestana.
 *
 * Nace de una auditoria: catorce salidas llevaban dos dias esperando firma. No
 * faltaba la pantalla —existe y funciona—, faltaba que se viera sin entrar. Una
 * pestana que dice lo mismo con catorce esperando que con ninguna obliga a
 * acordarse de mirar, y de eso nadie se acuerda todos los dias.
 *
 * Se refresca con el latido, que ya late cada 45 segundos mientras la pestana
 * del navegador esta a la vista y se calla cuando no lo esta.
 */
function usePendientes(): Pendientes {
  const latido = useLatido();
  const [n, setN] = useState<Pendientes>({ salidas: 0, productos: 0, rechazos_sin_ver: 0 });

  useEffect(() => {
    let vivo = true;
    supabase()
      .rpc('app_pendientes')
      .then(({ data, error }) => {
        if (!vivo || error || !data) return;
        const d = data as Record<string, unknown>;
        setN({
          salidas: Number(d['salidas'] ?? 0),
          productos: Number(d['productos'] ?? 0),
          rechazos_sin_ver: Number(d['rechazos_sin_ver'] ?? 0),
        });
      });
    return () => {
      vivo = false;
    };
  }, [latido]);

  return n;
}

function usePuedeGestionarObras(): boolean {
  return usePermiso('product.approve');
}

/**
 * Las obras a las que sale el material.
 *
 * Toda salida se registra contra una obra: es lo que permite saber a donde se
 * fue. Pero no habia forma de crear ninguna —ni pantalla ni funcion— y
 * carpinteria no tenia ni una, asi que su almacenista no podia registrar una
 * sola salida y nadie podia arreglarlo sin entrar a la base a mano.
 *
 * Esta pantalla es AHORA EL UNICO camino, porque el telefono volvio a solo
 * elegir de la lista. Eso obliga a que aqui se pueda hacer todo: dar de alta,
 * CORREGIR una que se escribio mal y RETIRAR una que sobra. Sin las dos
 * ultimas, cerrar el permiso del telefono habria dejado el catalogo tan
 * intocable como antes —y una obra mal escrita, mal escrita para siempre.
 *
 * Retirar tiene dos finales, y los decide la obra: si nunca se uso se BORRA;
 * si tiene movimientos se ARCHIVA. Borrar la segunda dejaria salidas de
 * material apuntando al vacio.
 */
function Obras({ division }: { division: string }) {
  const latido = useLatido();
  const puedeGestionar = usePuedeGestionarObras();
  const [filas, setFilas] = useState<Obra[] | null>(null);
  const [nombre, setNombre] = useState('');
  const [codigo, setCodigo] = useState('');
  const [trabajando, setTrabajando] = useState(false);
  const [aviso, setAviso] = useState<string | null>(null);
  const [recarga, setRecarga] = useState(0);
  const divisionCargada = useRef<string | null>(null);

  // Cual se esta corrigiendo, y con que valores.
  const [editando, setEditando] = useState<string | null>(null);
  const [nombreEd, setNombreEd] = useState('');
  const [codigoEd, setCodigoEd] = useState('');
  // Retirar pide confirmacion: es la unica accion de esta pantalla que quita
  // algo, y un dedo resbalado en una lista de treinta obras no deberia poder.
  const [confirmando, setConfirmando] = useState<string | null>(null);

  useEffect(() => {
    let vivo = true;
    if (divisionCargada.current !== division) {
      setFilas(null);
      divisionCargada.current = division;
    }
    supabase()
      .from('projects')
      .select('id, code, name, status, business_units!inner(slug)')
      .eq('business_units.slug', division)
      .order('name')
      .then(({ data, error }) => {
        if (!vivo) return;
        anotarResultado(error?.message);
        if (error) setAviso(mensajeDeError(error.message));
        else setFilas((data ?? []) as unknown as Obra[]);
      });
    return () => {
      vivo = false;
    };
  }, [division, latido, recarga]);

  async function crear(): Promise<void> {
    setTrabajando(true);
    setAviso(null);
    const { data, error } = await supabase().rpc('app_create_project', {
      p_business_unit: division,
      p_code: codigo.trim() === '' ? null : codigo,
      p_name: nombre,
      p_notes: null,
    });
    const r = data as { outcome: string; message?: string; code?: string } | null;
    setTrabajando(false);

    if (error || (r?.outcome !== 'APPLIED' && r?.outcome !== 'DUPLICATE')) {
      setAviso(mensajeDeError(error?.message) ?? r?.message ?? 'No se pudo dar de alta la obra.');
      return;
    }
    setAviso(
      r.outcome === 'DUPLICATE'
        ? 'Esa obra ya estaba dada de alta.'
        : `Obra dada de alta con el código ${r.code}. `
          + 'Los teléfonos la verán al sincronizar.',
    );
    setNombre('');
    setCodigo('');
    setRecarga((n) => n + 1);
  }

  function abrirEdicion(o: Obra): void {
    setEditando(o.id);
    setConfirmando(null);
    setNombreEd(o.name);
    setCodigoEd(o.code);
    setAviso(null);
  }

  async function guardar(o: Obra): Promise<void> {
    setTrabajando(true);
    setAviso(null);
    const { data, error } = await supabase().rpc('app_update_project', {
      p_project_id: o.id,
      p_name: nombreEd,
      p_code: codigoEd,
      p_notes: null,
      p_status: null,
    });
    const r = data as
      { outcome: string; message?: string; code?: string; code_changed?: boolean } | null;
    setTrabajando(false);

    if (error || (r?.outcome !== 'APPLIED' && r?.outcome !== 'DUPLICATE')) {
      setAviso(mensajeDeError(error?.message) ?? r?.message ?? 'No se pudo corregir la obra.');
      return;
    }
    // El codigo es lo que el telefono lleva guardado dentro de las salidas
    // que todavia no ha enviado. Cambiarlo con una en cola la hace rechazar
    // al sincronizar, asi que se dice, no se deja que se descubra.
    setAviso(
      r.code_changed
        ? `Obra corregida. Ojo: cambió el código a ${r.code}. `
          + 'Si alguien tenía una salida sin enviar para esta obra, se le rechazará; '
          + 'dígale que la capture otra vez.'
        : 'Obra corregida.',
    );
    setEditando(null);
    setRecarga((n) => n + 1);
  }

  async function retirar(o: Obra): Promise<void> {
    setTrabajando(true);
    setAviso(null);
    const { data, error } = await supabase().rpc('app_delete_project', { p_project_id: o.id });
    const r = data as { outcome: string; message?: string; mode?: string } | null;
    setTrabajando(false);
    setConfirmando(null);

    if (error || (r?.outcome !== 'APPLIED' && r?.outcome !== 'DUPLICATE')) {
      setAviso(mensajeDeError(error?.message) ?? r?.message ?? 'No se pudo retirar la obra.');
      return;
    }
    setAviso(r?.message ?? 'Obra retirada.');
    setRecarga((n) => n + 1);
  }

  async function reactivar(o: Obra): Promise<void> {
    setTrabajando(true);
    setAviso(null);
    const { data, error } = await supabase().rpc('app_update_project', {
      p_project_id: o.id,
      p_name: null,
      p_code: null,
      p_notes: null,
      p_status: 'ACTIVO',
    });
    const r = data as { outcome: string; message?: string } | null;
    setTrabajando(false);

    if (error || (r?.outcome !== 'APPLIED' && r?.outcome !== 'DUPLICATE')) {
      setAviso(mensajeDeError(error?.message) ?? r?.message ?? 'No se pudo reactivar la obra.');
      return;
    }
    setAviso(`"${o.name}" vuelve a estar activa. Los teléfonos la verán al sincronizar.`);
    setRecarga((n) => n + 1);
  }

  const activas = (filas ?? []).filter((o) => o.status === 'ACTIVO');
  const retiradas = (filas ?? []).filter((o) => o.status !== 'ACTIVO');

  function filaDeObra(o: Obra, activa: boolean): React.ReactNode {
    if (editando === o.id) {
      return (
        <div
          key={o.id}
          style={{
            display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'flex-end',
            padding: 14, borderRadius: radios.md,
            border: `1px solid ${colores.lineaFuerte}`, background: colores.papel,
          }}
        >
          <div style={{ flex: '2 1 220px' }}>
            <Campo etiqueta="Nombre" valor={nombreEd} alCambiar={setNombreEd} autoFoco />
          </div>
          <div style={{ flex: '1 1 150px' }}>
            <Campo
              etiqueta="Código"
              valor={codigoEd}
              alCambiar={setCodigoEd}
              ayuda="Es lo que viaja en la salida. Cámbielo solo si hace falta."
            />
          </div>
          <Boton
            tono="marca"
            onClick={() => void guardar(o)}
            disabled={trabajando || nombreEd.trim() === ''}
          >
            {trabajando ? 'Guardando…' : 'Guardar'}
          </Boton>
          <Boton onClick={() => setEditando(null)}>Cancelar</Boton>
        </div>
      );
    }

    return (
      <div
        key={o.id}
        style={{
          display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center',
          justifyContent: 'space-between',
          padding: '11px 15px', borderRadius: radios.md,
          border: `1px solid ${colores.linea}`,
          background: activa ? colores.papel : 'transparent',
          opacity: activa ? 1 : 0.62,
        }}
      >
        <span style={{ display: 'inline-flex', alignItems: 'baseline', gap: 10 }}>
          <strong style={{ fontSize: 15 }}>{o.name}</strong>
          <code style={{ fontSize: 11, color: colores.tintaDebil }}>{o.code}</code>
          {!activa && (
            <span style={{ fontSize: 12, color: colores.tintaTenue }}>
              retirada · no aparece en los teléfonos
            </span>
          )}
        </span>

        {puedeGestionar && (
          <span style={{ display: 'inline-flex', gap: 8, flexWrap: 'wrap' }}>
            {activa ? (
              <>
                <Boton onClick={() => abrirEdicion(o)} disabled={trabajando}>Editar</Boton>
                {confirmando === o.id ? (
                  <>
                    <Boton
                      tono="rechazar"
                      onClick={() => void retirar(o)}
                      disabled={trabajando}
                    >
                      Sí, retirar
                    </Boton>
                    <Boton onClick={() => setConfirmando(null)}>No</Boton>
                  </>
                ) : (
                  <Boton
                    onClick={() => { setConfirmando(o.id); setEditando(null); setAviso(null); }}
                    disabled={trabajando}
                  >
                    Retirar
                  </Boton>
                )}
              </>
            ) : (
              <Boton tono="marca" onClick={() => void reactivar(o)} disabled={trabajando}>
                Reactivar
              </Boton>
            )}
          </span>
        )}
      </div>
    );
  }

  return (
    <Tarjeta>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
        <div>
          <span style={rotulo}>Obras de {NOMBRE_DIVISION[division]}</span>
          <h2 style={{ margin: '2px 0 0' }}>A dónde sale el material</h2>
          <p style={{ margin: '6px 0 0', fontSize: 14, color: colores.tintaTenue }}>
            Toda salida se registra contra una obra, y en el teléfono la obra se{' '}
            <strong>elige de esta lista</strong>: no se escribe. Si la obra no está aquí,
            el almacenista no puede sacar material para ella.
          </p>
        </div>

        {puedeGestionar && (
          <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', alignItems: 'flex-end' }}>
            <div style={{ flex: '2 1 240px' }}>
              <Campo etiqueta="Nombre de la obra" valor={nombre} alCambiar={setNombre} />
            </div>
            <div style={{ flex: '1 1 160px' }}>
              <Campo
                etiqueta="Código"
                valor={codigo}
                alCambiar={setCodigo}
                ayuda="Opcional: sale del nombre."
              />
            </div>
            <Boton
              tono="marca"
              onClick={() => void crear()}
              disabled={trabajando || nombre.trim() === ''}
            >
              {trabajando ? 'Dando de alta…' : 'Dar de alta'}
            </Boton>
          </div>
        )}

        {aviso && <Aviso>{aviso}</Aviso>}

        {filas === null ? (
          <Cargando />
        ) : activas.length === 0 ? (
          <Aviso>
            {NOMBRE_DIVISION[division]} no tiene ninguna obra activa. Hasta que haya una, sus
            almacenistas no pueden registrar salidas.
          </Aviso>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {activas.map((o) => filaDeObra(o, true))}
          </div>
        )}

        {retiradas.length > 0 && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            <span style={rotulo}>Retiradas</span>
            <p style={{ margin: 0, fontSize: 13, color: colores.tintaTenue }}>
              Siguen aquí porque tienen movimientos registrados y su historia no se borra.
              No aparecen en los teléfonos.
            </p>
            {retiradas.map((o) => filaDeObra(o, false))}
          </div>
        )}
      </div>
    </Tarjeta>
  );
}

/**
 * Envuelve la carga para darle las unidades del catalogo.
 *
 * Las unidades tienen que venir del servidor y no de una lista escrita a mano:
 * el importador compara contra ellas para decidir si una unidad del archivo
 * existe, y una lista desactualizada aqui marcaria como dudosas unidades que
 * son perfectamente validas.
 */
function CargaDeArchivo({ division, alCargar }: { division: string; alCargar: () => void }) {
  const unidades = useUnidades();
  return <CargaInteligente division={division} unidades={unidades} alCargar={alCargar} />;
}

function AltaDeProducto({ divisionInicial, alCrear }: {
  divisionInicial: string;
  alCrear: () => void;
}) {
  const clasificaciones = useClasificaciones();

  const [division, setDivision] = useState(divisionInicial);
  const [codigo, setCodigo] = useState('');
  const [nombre, setNombre] = useState('');
  const [unidad, setUnidad] = useState('PZA');
  const [clasificacion, setClasificacion] = useState('');
  const [destino, setDestino] = useState('');
  const [minimo, setMinimo] = useState('');
  const [notas, setNotas] = useState('');

  const unidades = useUnidades();
  const [guardando, setGuardando] = useState(false);
  const [hecho, setHecho] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const minimoInvalido = minimo.trim() !== '' && !Number.isFinite(Number(minimo));
  const listo = codigo.trim() !== '' && nombre.trim() !== '' && !minimoInvalido;

  async function guardar() {
    setGuardando(true);
    setError(null);
    setHecho(null);

    const { data, error: e } = await supabase().rpc('app_create_product', {
      p_business_unit: division,
      p_code: codigo.trim(),
      p_name: nombre.trim(),
      p_unit_code: unidad,
      p_classification: clasificacion || null,
      p_destination: destino.trim() || null,
      p_min_stock: minimo.trim() === '' ? null : Number(minimo),
      p_notes: notas.trim() || null,
    });

    setGuardando(false);

    if (e) {
      setError(mensajeDeError(e.message));
      return;
    }

    const r = data as { outcome: string; message: string };
    if (r.outcome !== 'CREATED') {
      // La funcion contesta con un motivo entendible en vez de reventar. Se
      // enseña tal cual: "ya fue propuesto desde la app" le dice al
      // administrador exactamente a donde ir.
      setError(mensajeDeError(r.message));
      return;
    }

    setHecho(r.message);

    // Se limpia lo que cambia de un producto al siguiente y se conserva lo que
    // se repite. Quien esta cargando veinte cubrecantos de la misma obra no
    // tiene que volver a elegir division, unidad, clasificacion y destino
    // veinte veces.
    setCodigo('');
    setNombre('');
    setNotas('');
    alCrear();
  }

  const vistaPrevia = leyendaDe(clasificaciones, clasificacion || null);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16, maxWidth: 720 }}>
      <TituloDePagina sub={<>Entra directo al catálogo, sin pasar por autorización: aquí ya está firmando quien
          autoriza. Arranca con existencia 0 — lo que hay en el estante se registra como entrada.</>}>
        Dar de alta un producto
      </TituloDePagina>

      {hecho && <Aviso>{hecho}</Aviso>}
      {error && <Alerta>{error}</Alerta>}

      <Tarjeta style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <Selector
          etiqueta="División"
          valor={division}
          alCambiar={setDivision}
          opciones={['pvc', 'carpinteria'].map((d) => ({
            valor: d,
            texto: NOMBRE_DIVISION[d] ?? d,
          }))}
          ayuda="Los inventarios están separados: el producto solo existirá en la división que elija."
        />

        <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 220px' }}>
            <Campo
              etiqueta="Código"
              valor={codigo}
              alCambiar={setCodigo}
              autoFoco
              ayuda="Tal como viene del proveedor. Se guarda como texto: los ceros de delante no se pierden."
            />
          </div>
          <div style={{ flex: '2 1 300px' }}>
            <Campo etiqueta="Nombre" valor={nombre} alCambiar={setNombre} />
          </div>
        </div>

        <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 200px' }}>
            <Selector
              etiqueta="Unidad"
              valor={unidad}
              alCambiar={setUnidad}
              opciones={
                unidades.length > 0
                  ? unidades.map((u) => ({ valor: u.code, texto: `${u.code} — ${u.name}` }))
                  : [{ valor: 'PZA', texto: 'PZA' }]
              }
            />
          </div>
          <div style={{ flex: '1 1 200px' }}>
            <Selector
              etiqueta="Clasificación"
              valor={clasificacion}
              alCambiar={setClasificacion}
              opciones={[
                { valor: '', texto: 'Sin clasificar' },
                ...clasificaciones.map((c) => ({ valor: c.slug, texto: c.name })),
              ]}
            />
          </div>
          <div style={{ flex: '1 1 160px' }}>
            <Campo
              etiqueta="Mínimo"
              valor={minimo}
              alCambiar={setMinimo}
              ayuda={minimoInvalido ? 'Tiene que ser un número.' : 'Opcional. Avisa cuando baje de aquí.'}
            />
          </div>
        </div>

        <Campo
          etiqueta="Destino del material"
          valor={destino}
          alCambiar={setDestino}
          ayuda="A dónde va. Texto libre: se guarda tal como lo escriba."
        />

        <Campo etiqueta="Notas" valor={notas} alCambiar={setNotas} />

        {(clasificacion || destino.trim()) && (
          <div>
            <div
              style={{
                fontSize: 11,
                fontWeight: 600,
                letterSpacing: '.06em',
                color: colores.tintaDebil,
                textTransform: 'uppercase',
              }}
            >
              Se verá así
            </div>
            <div style={{ fontSize: 15, fontWeight: 600, marginTop: 6 }}>
              {nombre.trim() || 'Nombre del producto'}
            </div>
            <Leyenda {...vistaPrevia} destino={destino.trim() || null} />
          </div>
        )}

        <Boton tono="marca" disabled={!listo || guardando} onClick={() => void guardar()}>
          {guardando ? 'Dando de alta…' : 'Dar de alta'}
        </Boton>
      </Tarjeta>
    </div>
  );
}

function EnConstruccion({ que, porQue }: { que: string; porQue: string }) {
  return (
    <Tarjeta>
      <h2 style={{ margin: 0 }}>{que}</h2>
      <p style={{ color: colores.tintaTenue, fontSize: 14, marginBottom: 0 }}>{porQue}</p>
    </Tarjeta>
  );
}

/**
 * Cancelaria o carpinteria.
 *
 * Estaba escrito dentro del inventario. Al hacer falta tambien en el
 * movimiento del dia, copiarlo habria significado dos selectores que se
 * separan en cuanto alguien toque uno; y este ademas cambia el metal de toda
 * la pantalla, asi que dos versiones seria tener dos ambientes distintos.
 */
function SelectorDivision({
  division, alCambiar,
}: {
  division: string;
  alCambiar: (d: string) => void;
}) {
  return (
    <div style={{ display: 'flex', gap: 8 }}>
      {['pvc', 'carpinteria'].map((d) => (
        <button
          key={d}
          type="button"
          onClick={() => alCambiar(d)}
          style={{
            // Control segmentado: pastillas, no botones cuadrados. La division
            // elegida se eleva; la otra se queda plana.
            background: division === d ? colores.marcaRelleno : 'transparent',
            color: division === d ? colores.sobreAcento : colores.tintaTenue,
            border: `1px solid ${division === d ? colores.marcaRelleno : colores.linea}`,
            borderRadius: 999,
            boxShadow: division === d ? sombras.suave : 'none',
            padding: '9px 18px',
            fontSize: 14,
            fontWeight: 600,
            cursor: 'pointer',
            fontFamily: 'inherit',
          }}
        >
          {NOMBRE_DIVISION[d]}
        </button>
      ))}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Movimiento del dia                                                  */
/* ------------------------------------------------------------------ */

interface Actividad {
  movement_id: string;
  business_unit: string;
  occurred_at: string;
  movement_type: string;
  source: string;
  origen: string;
  product_code: string;
  product_name: string;
  unit_code: string | null;
  quantity: number;
  balance_after: number;
  autor: string | null;
}

/** El dia de hoy en la zona horaria del equipo, en formato aaaa-mm-dd. */
function hoyLocal(): string {
  const d = new Date();
  const mes = String(d.getMonth() + 1).padStart(2, '0');
  const dia = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${mes}-${dia}`;
}

interface Rechazo {
  id: string;
  product_code: string | null;
  product_name: string | null;
  movement_kind: string | null;
  quantity: number | null;
  error_code: string;
  message: string | null;
  actor_name: string | null;
  intentos: number;
  visto_por_ultima_vez: string;
}

/**
 * Lo que el servidor le dijo que NO a un telefono.
 *
 * Va arriba del movimiento del dia porque es la respuesta a la pregunta que
 * trae aqui a la gente: alguien capturo algo, no aparece, y hasta ahora no
 * habia forma de saber por que. Un rechazo no es un movimiento y no puede
 * mezclarse con ellos en la misma tabla: no paso nada, y esa es justamente la
 * noticia.
 *
 * No se acota al dia elegido. Un rechazo del martes sigue siendo material que
 * nunca se registro; esconderlo el miercoles seria perderlo para siempre.
 */
/**
 * El nombre de la obra que falta, sacado del propio mensaje del rechazo.
 *
 * El servidor responde: No existe el proyecto "A nave 1". Ese texto entre
 * comillas es EXACTAMENTE lo que se tecleo en el telefono, y es lo unico que
 * hara coincidir la obra cuando se reintente.
 *
 * Es lo que evita el error que costo dos dias: se dio de alta "nave 1" -sin la
 * A- y ademas en la division equivocada. Ninguna de las dos cosas se nota
 * mirando, y las dos hacen que el reintento vuelva a fallar igual.
 */
function obraQueFalta(mensaje: string | null): string | null {
  if (!mensaje) return null;
  const m = /No existe (?:el proyecto|la obra) "([^"]+)"/i.exec(mensaje);
  return m?.[1]?.trim() || null;
}

function Rechazos({ division }: { division: string }) {
  const latido = useLatido();
  const [filas, setFilas] = useState<Rechazo[]>([]);
  const [creandoObra, setCreandoObra] = useState<string | null>(null);
  const [avisoObra, setAvisoObra] = useState<string | null>(null);

  async function altaDeObraQueFalta(nombre: string): Promise<void> {
    setCreandoObra(nombre);
    setAvisoObra(null);
    const { data, error } = await supabase().rpc('app_create_project', {
      // La division de la PANTALLA, que es la del rechazo. No una elegida a
      // mano en otro sitio: ahi es donde se cuela el error.
      p_business_unit: division,
      p_code: null,
      p_name: nombre,
      p_notes: null,
    });
    const r = data as { outcome: string; message?: string } | null;
    setCreandoObra(null);

    if (error || (r?.outcome !== 'APPLIED' && r?.outcome !== 'DUPLICATE')) {
      setAvisoObra(error?.message ?? r?.message ?? 'No se pudo dar de alta la obra.');
      return;
    }
    setAvisoObra(
      `Obra "${nombre}" dada de alta en ${NOMBRE_DIVISION[division]}. `
      + 'Pídale a quien la capturó que pulse REINTENTAR en su teléfono.',
    );
  }

  useEffect(() => {
    let vivo = true;
    supabase()
      .from('sync_rejections_view')
      .select('*')
      .eq('business_unit', division)
      .is('resuelto_at', null)
      .order('visto_por_ultima_vez', { ascending: false })
      .limit(25)
      .then(({ data, error }) => {
        // Sin ruido si falla: quien no tiene permiso para verlos simplemente no
        // los ve, y esta pantalla tiene otro trabajo que hacer.
        if (vivo && !error) setFilas((data ?? []) as unknown as Rechazo[]);
      });
    return () => {
      vivo = false;
    };
  }, [division, latido]);

  if (filas.length === 0) return null;

  return (
    <Tarjeta>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div>
          <span style={{ ...rotulo, color: colores.avisoTexto }}>No se registró</span>
          <h2 style={{ margin: '2px 0 0' }}>
            {filas.length} {filas.length === 1 ? 'captura rechazada' : 'capturas rechazadas'}
          </h2>
          <p style={{ margin: '6px 0 0', fontSize: 14, color: colores.tintaTenue }}>
            Alguien lo capturó en su teléfono y el servidor no lo aceptó. El material{' '}
            <strong>no está contado</strong> en las existencias. Al resolver el motivo, esa
            persona solo tiene que volver a pulsar Sincronizar.
          </p>
        </div>

        {avisoObra && <Aviso>{avisoObra}</Aviso>}

        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {filas.map((r) => (
            <div
              key={r.id}
              style={{
                display: 'flex',
                gap: 14,
                flexWrap: 'wrap',
                alignItems: 'baseline',
                paddingTop: 12,
                borderTop: `1px solid ${colores.linea}`,
              }}
            >
              <div style={{ flex: '1 1 240px' }}>
                <code style={{ fontSize: 12, color: colores.tintaDebil }}>
                  {r.product_code ?? '—'}
                </code>
                <div style={{ fontSize: 14 }}>
                  {r.product_name ?? <em style={{ color: colores.tintaDebil }}>sin dar de alta</em>}
                </div>
                <div style={{ fontSize: 13, color: colores.avisoTexto, marginTop: 4 }}>
                  {r.message ?? r.error_code}
                </div>
              </div>
              <div style={{ textAlign: 'right', minWidth: 150 }}>
                {/* La obra que falta se da de alta desde aqui, con el nombre
                    EXACTO y en la division correcta. Escribirlo a mano en otra
                    pantalla es como se creo "nave 1" en cancelaria cuando
                    hacia falta "A nave 1" en carpinteria: el reintento volvio
                    a fallar y nadie entendia por que. */}
                {obraQueFalta(r.message) && (
                  <Boton
                    tono="marca"
                    onClick={() => void altaDeObraQueFalta(obraQueFalta(r.message)!)}
                    disabled={creandoObra !== null}
                  >
                    {creandoObra === obraQueFalta(r.message)
                      ? 'Dando de alta…'
                      : `Dar de alta "${obraQueFalta(r.message)}"`}
                  </Boton>
                )}
                <div style={{ fontSize: 13, marginTop: 8 }}>{r.actor_name ?? '—'}</div>
                <span style={{ ...rotulo, color: colores.tintaDebil }}>
                  {r.movement_kind ?? ''}
                  {r.quantity !== null ? ` · ${Number(r.quantity)}` : ''}
                </span>
                {/* Cuantas veces lo ha intentado. Es la diferencia entre "se le
                    paso" y "lleva toda la mañana peleandose con esto". */}
                {Number(r.intentos) > 1 && (
                  <div style={{ fontSize: 12, color: colores.tintaDebil, marginTop: 2 }}>
                    {r.intentos} intentos
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </Tarjeta>
  );
}

/**
 * Todo lo que se movio en un dia.
 *
 * Hasta ahora, para saber que habia pasado en la nave habia que abrir producto
 * por producto y mirar su historial. Con ochenta y siete productos eso no se
 * hace, y en la practica nadie lo sabia.
 *
 * Arranca en HOY y en lo capturado desde los TELEFONOS, que es la pregunta que
 * se hace al cerrar la jornada: que movio la gente de la nave. Lo hecho desde
 * el panel se puede sumar con el interruptor, util cuando un numero no cuadra
 * y hay que ver todo lo que le paso a un producto.
 */
function MovimientoDelDia({ division }: { division: string }) {
  const latido = useLatido();
  const [dia, setDia] = useState(hoyLocal());
  const [soloTelefonos, setSoloTelefonos] = useState(true);
  const [filas, setFilas] = useState<Actividad[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const diaCargado = useRef<string | null>(null);

  useEffect(() => {
    let vivo = true;
    // Igual que en el inventario: solo se vacia al cambiar de dia o division,
    // nunca en un latido, o la tabla parpadearia sola cada minuto.
    const clave = `${dia}|${division}`;
    if (diaCargado.current !== clave) {
      setFilas(null);
      diaCargado.current = clave;
    }
    setError(null);

    // El dia entero en hora local, convertido a instantes: de las 00:00 a las
    // 00:00 del siguiente. Comparar contra la fecha en texto fallaria con cada
    // movimiento capturado despues de las seis de la tarde, que en UTC ya cae
    // en el dia siguiente.
    const desde = new Date(`${dia}T00:00:00`);
    const hasta = new Date(desde.getTime() + 24 * 60 * 60 * 1000);

    supabase()
      .from('daily_activity')
      .select('*')
      .eq('business_unit', division)
      .gte('occurred_at', desde.toISOString())
      .lt('occurred_at', hasta.toISOString())
      .order('occurred_at', { ascending: false })
      .then(({ data, error: e }) => {
        if (!vivo) return;
        if (e) setError(mensajeDeError(e.message));
        else setFilas((data ?? []) as unknown as Actividad[]);
      });

    return () => {
      vivo = false;
    };
  }, [dia, division, latido]);

  const visibles = useMemo(
    () => (filas ?? []).filter((f) => (soloTelefonos ? f.source === 'APP' : true)),
    [filas, soloTelefonos],
  );

  if (error) return <Alerta>{error}</Alerta>;
  if (!filas) return <Cargando />;

  const entradas = visibles.filter((f) => esEntrada(f.movement_type)).length;
  const salidas = visibles.length - entradas;
  const desdePanel = filas.filter((f) => f.source !== 'APP').length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 22 }}>
      <div>
        <h1 style={{ margin: 0 }}>Movimiento del día</h1>
        <span style={{ ...rotulo, display: 'block', marginTop: 2 }}>
          {NOMBRE_DIVISION[division]} · {visibles.length}{' '}
          {visibles.length === 1 ? 'movimiento' : 'movimientos'} · {entradas} de entrada ·{' '}
          {salidas} de salida
        </span>
      </div>

      <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', alignItems: 'center' }}>
        <input
          type="date"
          value={dia}
          max={hoyLocal()}
          onChange={(e) => setDia(e.target.value)}
          style={{
            border: `1px solid ${colores.linea}`,
            borderRadius: radios.md,
            background: colores.papel,
            color: colores.tinta,
            minHeight: 50,
            padding: '13px 18px',
            fontSize: 15,
            fontFamily: 'inherit',
            colorScheme: 'dark',
          }}
        />
        {dia !== hoyLocal() && <Boton onClick={() => setDia(hoyLocal())}>Hoy</Boton>}
        <div style={{ flex: 1 }} />
        {desdePanel > 0 && (
          <Interruptor encendido={!soloTelefonos} alCambiar={(v) => setSoloTelefonos(!v)}>
            Sumar {desdePanel} del panel
          </Interruptor>
        )}
      </div>

      {visibles.length === 0 ? (
        <Aviso>
          {soloTelefonos
            ? 'Nadie capturó nada desde un teléfono este día. Si esperabas movimientos, revisa que el almacenista haya pulsado Sincronizar y que su teléfono tenga señal.'
            : 'No hubo ningún movimiento este día.'}
        </Aviso>
      ) : (
        <Tarjeta sinRelleno style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ textAlign: 'left', borderBottom: `2px solid ${colores.linea}` }}>
                <Th>Hora</Th>
                <Th>Producto</Th>
                <Th>Qué pasó</Th>
                <Th alineado="right">Cantidad</Th>
                <Th alineado="right">Quedó</Th>
                <Th>Quién</Th>
              </tr>
            </thead>
            <tbody>
              {visibles.map((f) => (
                <tr key={f.movement_id} style={{ borderBottom: `1px solid ${colores.linea}` }}>
                  <Td>
                    <span className="cifra" style={{ fontSize: 13 }}>
                      {new Date(f.occurred_at).toLocaleTimeString('es-MX', {
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                    </span>
                  </Td>
                  <Td>
                    <code style={{ fontSize: 12, color: colores.tintaDebil }}>
                      {f.product_code}
                    </code>
                    <div>{f.product_name}</div>
                  </Td>
                  <Td>
                    {NOMBRE_TIPO[f.movement_type] ?? f.movement_type}
                    {/* De donde salio. Es lo primero que se pregunta cuando un
                        numero no cuadra: lo puso la nave o el escritorio. */}
                    {!soloTelefonos && (
                      <span style={{ ...rotulo, marginLeft: 10, color: colores.tintaDebil }}>
                        {f.origen}
                      </span>
                    )}
                  </Td>
                  <Td alineado="right">
                    <span
                      className="cifra"
                      style={{
                        fontSize: 15,
                        fontWeight: 600,
                        color: esEntrada(f.movement_type) ? colores.aprobar : colores.rechazar,
                      }}
                    >
                      {esEntrada(f.movement_type) ? '+' : '−'}
                      {Math.abs(Number(f.quantity))}
                    </span>{' '}
                    <span style={{ color: colores.tintaDebil, fontSize: 12 }}>{f.unit_code}</span>
                  </Td>
                  <Td alineado="right">
                    <span className="cifra" style={{ fontSize: 15 }}>
                      {Number(f.balance_after)}
                    </span>
                  </Td>
                  <Td>{f.autor ?? '—'}</Td>
                </tr>
              ))}
            </tbody>
          </table>
        </Tarjeta>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Herramientas y maquinaria                                           */
/* ------------------------------------------------------------------ */

interface Herramienta {
  tool_id: string;
  code: string;
  name: string;
  model: string | null;
  serial_number: string | null;
  status: string;
  condition: string;
  holder: string | null;
  lent_at: string | null;
  due_at: string | null;
  is_overdue: boolean;
  project_name: string | null;
}

const ESTADO_HERRAMIENTA: Record<string, { texto: string; tono: 'bien' | 'fuera' | 'mal' }> = {
  DISPONIBLE: { texto: 'En el almacén', tono: 'bien' },
  PRESTADA: { texto: 'Prestada', tono: 'fuera' },
  EN_OBRA: { texto: 'En obra', tono: 'fuera' },
  EN_MANTENIMIENTO: { texto: 'En mantenimiento', tono: 'mal' },
  DANADA: { texto: 'Dañada', tono: 'mal' },
  PERDIDA: { texto: 'Perdida', tono: 'mal' },
};

/**
 * Herramientas y maquinaria.
 *
 * Una herramienta no se agota: se presta y se devuelve. Por eso no vive en el
 * catalogo de material, no descuenta existencia y no tiene minimo. La pregunta
 * que resuelve esta pantalla es otra: donde esta cada cosa y quien la tiene.
 *
 * Por eso lo que esta FUERA va arriba. Una lista ordenada por nombre sirve
 * para un inventario; para buscar un rotomartillo un martes por la mañana, lo
 * que hace falta es ver de un golpe lo que no esta y quien se lo llevo.
 */
function Herramientas({ division }: { division: string }) {
  const latido = useLatido();
  const [filas, setFilas] = useState<Herramienta[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [recarga, setRecarga] = useState(0);
  const divisionCargada = useRef<string | null>(null);

  const [codigo, setCodigo] = useState('');
  const [nombre, setNombre] = useState('');
  const [modelo, setModelo] = useState('');
  const [serie, setSerie] = useState('');
  const [trabajando, setTrabajando] = useState(false);
  const [aviso, setAviso] = useState<string | null>(null);

  useEffect(() => {
    let vivo = true;
    if (divisionCargada.current !== division) {
      setFilas(null);
      divisionCargada.current = division;
    }
    supabase()
      .from('tools_catalog')
      .select('*')
      .eq('business_unit', division)
      .order('name')
      .then(({ data, error: e }) => {
        if (!vivo) return;
        if (e) setError(mensajeDeError(e.message));
        else {
          setError(null);
          setFilas((data ?? []) as unknown as Herramienta[]);
        }
      });
    return () => {
      vivo = false;
    };
  }, [division, latido, recarga]);

  async function darDeAlta(): Promise<void> {
    setTrabajando(true);
    setAviso(null);
    const { data, error: e } = await supabase().rpc('app_create_tool', {
      p_business_unit: division,
      p_code: codigo,
      p_name: nombre,
      p_brand: null,
      p_model: modelo.trim() || null,
      p_serial: serie.trim() || null,
      p_notes: null,
    });
    const r = data as { outcome: string; message?: string } | null;
    setTrabajando(false);

    if (e || (r?.outcome !== 'APPLIED' && r?.outcome !== 'DUPLICATE')) {
      setAviso(e?.message ?? r?.message ?? 'No se pudo dar de alta.');
      return;
    }
    setAviso(r.outcome === 'DUPLICATE' ? 'Ese código ya estaba dado de alta.' : 'Dada de alta.');
    setCodigo('');
    setNombre('');
    setModelo('');
    setSerie('');
    setRecarga((n) => n + 1);
  }

  if (error) return <Alerta>{error}</Alerta>;
  if (!filas) return <Cargando />;

  // Lo que esta fuera, primero. Y dentro de eso, lo vencido antes que el resto.
  const ordenadas = filas.slice().sort((a, b) => {
    const fuera = (h: Herramienta) => (h.holder ? 0 : 1);
    if (fuera(a) !== fuera(b)) return fuera(a) - fuera(b);
    if (a.is_overdue !== b.is_overdue) return a.is_overdue ? -1 : 1;
    return a.name.localeCompare(b.name, 'es');
  });

  const fuera = filas.filter((h) => h.holder).length;
  const vencidas = filas.filter((h) => h.is_overdue).length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 22 }}>
      <div>
        <h1 style={{ margin: 0 }}>Herramientas y maquinaria</h1>
        <span style={{ ...rotulo, display: 'block', marginTop: 2 }}>
          {NOMBRE_DIVISION[division]} · {filas.length}{' '}
          {filas.length === 1 ? 'pieza' : 'piezas'} · {fuera} fuera del almacén
          {vencidas > 0 ? ` · ${vencidas} con la fecha vencida` : ''}
        </span>
      </div>

      <Tarjeta>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div>
            <span style={rotulo}>Dar de alta</span>
            <p style={{ margin: '6px 0 0', fontSize: 14, color: colores.tintaTenue }}>
              Una herramienta no se agota: se presta y se devuelve. No descuenta existencia ni
              aparece en el inventario de material.
            </p>
          </div>
          <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', alignItems: 'flex-end' }}>
            <div style={{ flex: '1 1 130px' }}>
              <Campo etiqueta="Código" valor={codigo} alCambiar={setCodigo} />
            </div>
            <div style={{ flex: '2 1 220px' }}>
              <Campo etiqueta="Qué es" valor={nombre} alCambiar={setNombre} />
            </div>
            <div style={{ flex: '1 1 150px' }}>
              <Campo etiqueta="Modelo" valor={modelo} alCambiar={setModelo} />
            </div>
            <div style={{ flex: '1 1 150px' }}>
              <Campo etiqueta="Número de serie" valor={serie} alCambiar={setSerie} />
            </div>
            <Boton
              tono="marca"
              onClick={() => void darDeAlta()}
              disabled={trabajando || nombre.trim() === '' || codigo.trim() === ''}
            >
              {trabajando ? 'Dando de alta…' : 'Dar de alta'}
            </Boton>
          </div>
          {aviso && <Aviso>{aviso}</Aviso>}
        </div>
      </Tarjeta>

      {filas.length === 0 ? (
        <Aviso>
          {NOMBRE_DIVISION[division]} no tiene herramientas dadas de alta todavía.
        </Aviso>
      ) : (
        <Tarjeta sinRelleno style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ textAlign: 'left', borderBottom: `2px solid ${colores.linea}` }}>
                <Th>Código</Th>
                <Th>Herramienta</Th>
                <Th>Dónde está</Th>
                <Th>Quién la tiene</Th>
                <Th>Desde</Th>
              </tr>
            </thead>
            <tbody>
              {ordenadas.map((h) => {
                const est = ESTADO_HERRAMIENTA[h.status]
                  ?? { texto: h.status, tono: 'mal' as const };
                const color =
                  est.tono === 'bien' ? colores.aprobar
                  : est.tono === 'fuera' ? colores.avisoTexto
                  : colores.rechazar;
                return (
                  <tr
                    key={h.tool_id}
                    style={{ borderBottom: `1px solid ${colores.linea}` }}
                  >
                    <Td>
                      <code style={{ fontSize: 13 }}>{h.code}</code>
                    </Td>
                    <Td>
                      {h.name}
                      {(h.model || h.serial_number) && (
                        <div style={{ ...rotulo, color: colores.tintaDebil, marginTop: 2 }}>
                          {[h.model, h.serial_number].filter(Boolean).join(' · ')}
                        </div>
                      )}
                    </Td>
                    <Td>
                      <span style={{ color, fontSize: 13, fontWeight: 600, whiteSpace: 'nowrap' }}>
                        {est.texto}
                      </span>
                      {h.project_name && (
                        <div style={{ fontSize: 12, color: colores.tintaDebil }}>
                          {h.project_name}
                        </div>
                      )}
                    </Td>
                    <Td>{h.holder ?? '—'}</Td>
                    <Td>
                      {h.lent_at ? (
                        <span
                          className="cifra"
                          style={{
                            fontSize: 13,
                            color: h.is_overdue ? colores.rechazar : colores.tinta,
                          }}
                        >
                          {new Date(h.lent_at).toLocaleDateString('es-MX', {
                            day: '2-digit',
                            month: 'short',
                          })}
                          {h.is_overdue ? ' · vencida' : ''}
                        </span>
                      ) : (
                        '—'
                      )}
                    </Td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </Tarjeta>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Aplicacion                                                          */
/* ------------------------------------------------------------------ */

type Vista =
  | 'inventario' | 'dia' | 'herramientas' | 'obras' | 'alta' | 'salidas'
  | 'productos' | 'carga';

function App() {
  const [hayConexion, setHayConexion] = useState(() => conexionGuardada() !== null);
  const [sesion, setSesion] = useState<Session | null | undefined>(undefined);
  const [division, setDivision] = useState('pvc');
  const [vista, setVista] = useState<Vista>('inventario');
  const enLinea = useEnLinea();
  const pendientes = usePendientes();

  /**
   * Si la base CONTESTA, que no es lo mismo que si hay red.
   *
   * `useEnLinea` mira `navigator.onLine`, y eso promete que hay una interfaz de
   * red arriba: con el wifi de la nave conectado a un router sin internet dice
   * que si, y el punto de la cabecera se pintaba verde mientras ninguna
   * consulta llegaba a ningun sitio. El indicador mentia justo cuando mas falta
   * hacia que dijera la verdad.
   *
   * Esto lo alimenta cada consulta que termina. Las dos condiciones juntas son
   * lo unico que significa "al dia".
   */
  const [baseContesta, setBaseContesta] = useState(baseResponde);
  useEffect(() => alCambiarLaBase(setBaseContesta), []);
  const saludo = useSaludo(sesion?.user.id ?? null);
  const [saludado, setSaludado] = useState(false);

  /**
   * Sube cada vez que nace un producto. El inventario lo mira para volver a
   * leer: si no, alguien da de alta algo, se pasa a Inventario y no lo
   * encuentra —y lo razonable entonces es pensar que no se guardo y darlo de
   * alta otra vez.
   */
  const [altas, setAltas] = useState(0);
  const puedeDarDeAlta = usePuedeDarDeAlta();

  /**
   * El ambiente sigue a donde estas.
   *
   * La division pone el metal —dorado en carpinteria, el azul de la marca en
   * cancelaria— y la seccion lo modula dentro de esa misma familia. Todo el
   * cambio ocurre en dos atributos de la raiz: el color vive en variables CSS
   * (`index.html`), asi que ningun componente tiene que enterarse ni hay que ir
   * pasando el color de mano en mano por todo el arbol.
   */
  useEffect(() => {
    const raiz = document.documentElement;
    raiz.dataset['division'] = division;
    raiz.dataset['seccion'] = vista;
  }, [division, vista]);

  // Si la sesion la abrio un enlace de recuperacion, NO se entra al panel: se
  // pide antes la contrasena nueva. Sin esta bandera el enlace del correo metia
  // a la persona dentro con la contrasena vieja sin tocar, o sea sin recuperar
  // nada, y al dia siguiente volvia a estar fuera.
  const [recuperando, setRecuperando] = useState(
    // La marca viene en el fragmento de la URL. Se mira ya al arrancar porque
    // Supabase lo consume y lo borra antes de que llegue el evento.
    () => /type=recovery/.test(window.location.hash),
  );

  useEffect(() => {
    if (!hayConexion) return;
    const sb = supabase();
    sb.auth.getSession().then(({ data }) => setSesion(data.session));
    const { data: sub } = sb.auth.onAuthStateChange((evento, s) => {
      if (evento === 'PASSWORD_RECOVERY') setRecuperando(true);
      setSesion(s);
    });
    return () => sub.subscription.unsubscribe();
  }, [hayConexion]);

  if (!hayConexion) return <PantallaConexion alGuardar={() => setHayConexion(true)} />;
  if (sesion === undefined) return <Cargando texto="Abriendo…" />;
  if (sesion === null) return <PantallaEntrar />;
  if (recuperando) {
    return (
      <PantallaNuevaContrasena
        alTerminar={() => {
          // Se limpia el fragmento para que recargar no vuelva a pedirla.
          window.history.replaceState(null, '', window.location.pathname);
          setRecuperando(false);
        }}
      />
    );
  }

  return (
    <div style={{ minHeight: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* La bienvenida va ENCIMA de todo y solo la primera vez de la sesion.
          Puesta aqui y no dentro del contenido, porque el saludo es lo primero
          que se ve al entrar: si compartiera sitio con el inventario, se leeria
          como un aviso mas. */}
      {saludo && !saludado && (
        <Bienvenida
          texto={saludo.texto}
          nombre={saludo.nombre}
          alCerrar={() => {
            sessionStorage.setItem(YA_SALUDADO, '1');
            setSaludado(true);
          }}
        />
      )}
      <header
        style={{
          // Material translucido: la barra deja entrever lo que pasa por
          // debajo al desplazar. Es el sitio donde iOS 26 usa translucidez y
          // uno de los pocos donde aqui es seguro — no hay ninguna cifra de
          // existencia detras, solo navegacion.
          background: 'rgba(31,25,19,0.86)',
          backdropFilter: 'saturate(160%) blur(20px)',
          WebkitBackdropFilter: 'saturate(160%) blur(20px)',
          color: colores.tinta,
          // Un filete de laton al pie de la barra. Es el unico ornamento de
          // toda la pantalla, y por eso se nota: el remate metalico de un
          // mueble bueno, no una linea divisoria mas.
          borderBottom: `1px solid ${colores.marcaSuave}`,
          padding: '18px 28px',
          display: 'flex',
          alignItems: 'center',
          gap: 20,
          flexWrap: 'wrap',
          position: 'sticky',
          top: 0,
          zIndex: 20,
        }}
      >
        <div style={{ ...rotulo, fontSize: 10.5, color: colores.marca }}>
          Inventarios
        </div>
        <nav style={{ display: 'flex', gap: 4, flex: 1 }}>
          <Pestana activa={vista === 'inventario'} alPulsar={() => setVista('inventario')}>
            Inventario
          </Pestana>
          {puedeDarDeAlta && (
            <Pestana activa={vista === 'alta'} alPulsar={() => setVista('alta')}>
              Dar de alta
            </Pestana>
          )}
          {/* La carga de archivos va JUNTO a "Dar de alta", no escondida en
              ajustes: es lo mismo —meter productos al catalogo— pero de
              doscientos en doscientos. */}
          {puedeDarDeAlta && (
            <Pestana activa={vista === 'carga'} alPulsar={() => setVista('carga')}>
              Cargar archivo
            </Pestana>
          )}
          <Pestana activa={vista === 'dia'} alPulsar={() => setVista('dia')}>
            Movimiento del día
          </Pestana>
          <Pestana activa={vista === 'herramientas'} alPulsar={() => setVista('herramientas')}>
            Herramientas
          </Pestana>
          {/* Obras tiene pestaña propia y no vive dentro de "Dar de alta".
              Ahi estaba, y no se encontraba: quien necesita crear una obra
              llega buscando "obras", no "dar de alta un producto". Un sitio
              correcto donde nadie mira es un sitio equivocado. */}
          <Pestana activa={vista === 'obras'} alPulsar={() => setVista('obras')}>
            Obras
          </Pestana>
          <Pestana activa={vista === 'salidas'} alPulsar={() => setVista('salidas')}>
            Salidas por autorizar <Cuantas n={pendientes.salidas} />
          </Pestana>
          <Pestana activa={vista === 'productos'} alPulsar={() => setVista('productos')}>
            Productos por aprobar <Cuantas n={pendientes.productos} />
          </Pestana>
        </nav>
        <Pulso conectado={enLinea && baseContesta} />
        <span style={{ fontSize: 13, color: colores.tintaTenue }}>{sesion.user.email}</span>
        <MarcaCabecera />
        <button
          type="button"
          onClick={() => {
            // Los permisos del siguiente no son los de este.
            olvidarPermisos();
            void supabase().auth.signOut();
          }}
          style={{
            background: 'transparent',
            border: `1px solid ${colores.lineaFuerte}`,
            color: colores.tintaTenue,
            borderRadius: radios.sm,
            padding: '6px 12px',
            fontSize: 13,
            cursor: 'pointer',
            fontFamily: 'inherit',
          }}
        >
          Salir
        </button>
      </header>
      {/* El mismo hilo de metal que llevan las tarjetas, cerrando la cabecera. */}
      <div className="filete-metal" />

      <div style={{ padding: 24, display: 'flex', flexDirection: 'column', gap: 16, flex: 1 }}>
        {vista === 'inventario' && (
          <>
            <SelectorDivision division={division} alCambiar={setDivision} />
            <Inventario division={division} recargar={altas} />
          </>
        )}

        {vista === 'dia' && (
          <>
            <SelectorDivision division={division} alCambiar={setDivision} />
            <Rechazos division={division} />
            <MovimientoDelDia division={division} />
          </>
        )}

        {vista === 'obras' && (
          <>
            <SelectorDivision division={division} alCambiar={setDivision} />
            <Obras division={division} />
          </>
        )}

        {vista === 'carga' && puedeDarDeAlta && (
          <>
            <SelectorDivision division={division} alCambiar={setDivision} />
            <CargaDeArchivo division={division} alCargar={() => setAltas((n) => n + 1)} />
          </>
        )}

        {vista === 'alta' && puedeDarDeAlta && (
          <>
            <SelectorDivision division={division} alCambiar={setDivision} />
            <AltaDeProducto divisionInicial={division} alCrear={() => setAltas((n) => n + 1)} />
          </>
        )}

        {vista === 'herramientas' && (
          <>
            <SelectorDivision division={division} alCambiar={setDivision} />
            <Herramientas division={division} />
          </>
        )}

        {vista === 'salidas' && <SalidasPorAutorizar />}

        {vista === 'productos' && (
          <ProductosPorAprobar alAprobar={() => setAltas((n) => n + 1)} />
        )}
      </div>
    </div>
  );
}

function Pestana({
  children,
  activa,
  alPulsar,
}: {
  children: React.ReactNode;
  activa: boolean;
  alPulsar: () => void;
}) {
  return (
    <button
      type="button"
      onClick={alPulsar}
      style={{
        background: 'transparent',
        // La pestana activa no se marca con una caja: se marca con el color del
        // acento y un filete debajo. Menos ruido, y se ve antes.
        color: activa ? colores.marca : colores.tintaTenue,
        border: 'none',
        borderBottom: `2px solid ${activa ? colores.marca : 'transparent'}`,
        borderRadius: 0,
        padding: '8px 4px',
        marginRight: 18,
        fontSize: 14,
        fontWeight: activa ? 600 : 500,
        letterSpacing: '.02em',
        transition: 'color .25s ease, border-color .25s ease',
        cursor: 'pointer',
        fontFamily: 'inherit',
      }}
    >
      {children}
    </button>
  );
}

/**
 * El muestrario se decide AQUI, antes de montar `App`, y no dentro de ella.
 *
 * Al probarlo publicado se vio que dentro no bastaba: aunque `App` devolviera el
 * muestrario, sus efectos ya habian salido y pedian `app_pendientes` y
 * `has_permission` —dos viajes de unos 800 ms— para una pantalla que no ensena
 * ni un dato. Los efectos de React corren aunque lo que se pinte sea otra cosa;
 * lo unico que los evita es no montar el componente.
 */
const muestrario = new URLSearchParams(window.location.search).has('muestrario');

createRoot(document.getElementById('root')!).render(
  <Barrera>
    {muestrario ? <Muestrario /> : <App />}
  </Barrera>,
);
