/**
 * Lector de hojas de calculo, sin dependencias.
 *
 * POR QUE NO SE USA `exceljs`, QUE YA ESTA EN EL PROYECTO
 *
 * Porque esto tiene que correr EN EL NAVEGADOR. El panel no tiene servidor de
 * aplicacion —quien decide permisos es la seguridad por filas de PostgreSQL— y
 * meterle uno solo para leer un Excel seria anadir un sitio mas donde
 * equivocarse. `exceljs` esta escrito para Node: en un paquete de navegador
 * arrastra `stream` y `buffer`, y hacerlo entrar pesa mas —en trabajo y en
 * megabytes que se descargan— que leer la parte del formato que hace falta.
 *
 * Y hace falta poca. Un .xlsx es un ZIP con XML dentro, y de todo el formato
 * aqui solo se necesita una cosa: el texto de cada celda. Ni estilos, ni
 * formulas, ni graficos, ni formatos condicionales.
 *
 * QUE HACE POSIBLE ESTO SIN DEPENDENCIAS
 *
 * `DecompressionStream('deflate-raw')`, que es parte de la plataforma desde
 * hace anos: la descompresion —lo unico verdaderamente dificil— la hace el
 * navegador. Lo que queda es recorrer la tabla de contenidos del ZIP y sacar
 * texto de un XML, y eso son doscientas lineas.
 *
 * DONDE ESTA EL RIESGO, Y COMO SE CUBRE
 *
 * Un lector propio puede leer mal un archivo que otro leeria bien. Por eso las
 * pruebas leen los libros REALES de la empresa con este lector y con `exceljs`
 * a la vez, y exigen que digan lo MISMO celda por celda. Si algun dia dejan de
 * coincidir, se sabe antes de que nadie importe nada.
 *
 * LO QUE NO HACE, A PROPOSITO
 *
 * No convierte fechas. Un numero con formato de fecha sale como numero. El
 * importador no necesita fechas, y adivinar cual de los numeros de una hoja es
 * una fecha es exactamente el tipo de suposicion que mete basura en un
 * catalogo.
 */

/** Una celda: siempre texto o numero, nunca algo a medias. */
export type Celda = string | number | null;

export interface Hoja {
  nombre: string;
  /** Filas tal cual, sin encabezado interpretado. */
  filas: Celda[][];
}

/* ------------------------------------------------------------------ */
/* ZIP                                                                 */
/* ------------------------------------------------------------------ */

const FIRMA_FIN_CENTRAL = 0x06054b50;
const FIRMA_ENTRADA = 0x02014b50;

interface EntradaZip {
  nombre: string;
  metodo: number;
  desplazamiento: number;
  tamComprimido: number;
}

function leerTablaDeContenidos(datos: DataView): EntradaZip[] {
  // El indice del ZIP esta AL FINAL, no al principio: hay que buscarlo hacia
  // atras. El comentario final puede medir hasta 64 KB, asi que se busca en
  // esa ventana y no en todo el archivo.
  const desde = Math.max(0, datos.byteLength - 66_000);
  let fin = -1;
  for (let i = datos.byteLength - 22; i >= desde; i -= 1) {
    if (datos.getUint32(i, true) === FIRMA_FIN_CENTRAL) {
      fin = i;
      break;
    }
  }
  if (fin < 0) {
    throw new Error('El archivo no parece un Excel (.xlsx) ni un ZIP valido.');
  }

  const cuantas = datos.getUint16(fin + 10, true);
  const inicio = datos.getUint32(fin + 16, true);

  // ZIP64 marca estos campos a todo unos. Se dice claramente en vez de leer
  // basura: un archivo de mas de 65535 hojas o 4 GB no es un inventario.
  if (cuantas === 0xffff || inicio === 0xffffffff) {
    throw new Error('El archivo usa ZIP64 y este lector no lo admite. Guardelo de nuevo desde Excel.');
  }

  const entradas: EntradaZip[] = [];
  let p = inicio;
  for (let i = 0; i < cuantas; i += 1) {
    if (datos.getUint32(p, true) !== FIRMA_ENTRADA) break;
    const metodo = datos.getUint16(p + 10, true);
    const tamComprimido = datos.getUint32(p + 20, true);
    const largoNombre = datos.getUint16(p + 28, true);
    const largoExtra = datos.getUint16(p + 30, true);
    const largoComentario = datos.getUint16(p + 32, true);
    const desplazamiento = datos.getUint32(p + 42, true);

    const bytes = new Uint8Array(datos.buffer, datos.byteOffset + p + 46, largoNombre);
    entradas.push({
      nombre: new TextDecoder().decode(bytes),
      metodo,
      desplazamiento,
      tamComprimido,
    });

    p += 46 + largoNombre + largoExtra + largoComentario;
  }
  return entradas;
}

async function inflar(bytes: Uint8Array): Promise<Uint8Array> {
  // Sin `Blob`: los tipos de `BlobPart` cambian entre el entorno de Node y el
  // del navegador, y este archivo tiene que compilar en los dos. Un
  // ReadableStream construido a mano es identico en ambos.
  const origen = new ReadableStream<Uint8Array>({
    start(control) {
      control.enqueue(bytes);
      control.close();
    },
  });
  // El molde: `DecompressionStream` esta declarado de forma distinta en los
  // tipos de Node y en los del navegador —el parametro generico del
  // Uint8Array— y este archivo se compila en los dos. La forma real del objeto
  // es la misma en ambos: un par legible/escribible.
  const descompresor = new DecompressionStream('deflate-raw') as unknown as {
    readable: ReadableStream<Uint8Array>;
    writable: WritableStream<Uint8Array>;
  };
  const flujo = origen.pipeThrough(descompresor);
  const trozos: Uint8Array[] = [];
  let total = 0;
  const lector = flujo.getReader();
  for (;;) {
    const { done, value } = await lector.read();
    if (done) break;
    trozos.push(value as Uint8Array);
    total += (value as Uint8Array).length;
  }
  const salida = new Uint8Array(total);
  let i = 0;
  for (const t of trozos) {
    salida.set(t, i);
    i += t.length;
  }
  return salida;
}

async function extraer(
  datos: DataView,
  entrada: EntradaZip,
): Promise<string> {
  // El tamano del nombre y del extra se leen del encabezado LOCAL, no del
  // indice: no siempre coinciden, y usar los del indice desplaza el inicio de
  // los datos y produce basura.
  const base = entrada.desplazamiento;
  const largoNombre = datos.getUint16(base + 26, true);
  const largoExtra = datos.getUint16(base + 28, true);
  const inicio = base + 30 + largoNombre + largoExtra;

  const crudo = new Uint8Array(
    datos.buffer,
    datos.byteOffset + inicio,
    entrada.tamComprimido,
  );

  const bytes = entrada.metodo === 0 ? crudo : await inflar(crudo);
  return new TextDecoder().decode(bytes);
}

/* ------------------------------------------------------------------ */
/* XML                                                                 */
/* ------------------------------------------------------------------ */

const ENTIDADES: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'",
};

function desescapar(texto: string): string {
  return texto.replace(/&(#x?[0-9a-fA-F]+|[a-z]+);/g, (todo, cuerpo: string) => {
    if (cuerpo.startsWith('#x') || cuerpo.startsWith('#X')) {
      return String.fromCodePoint(parseInt(cuerpo.slice(2), 16));
    }
    if (cuerpo.startsWith('#')) {
      return String.fromCodePoint(parseInt(cuerpo.slice(1), 10));
    }
    return ENTIDADES[cuerpo] ?? todo;
  });
}

/** Todo el texto de los `<t>` que haya dentro de un trozo de XML. */
function textoDe(xml: string): string {
  // Un `<si>` puede venir partido en varios `<r><t>` cuando una parte del
  // texto lleva negrita. Concatenarlos es lo que hace que "TORNILLO **1/4**"
  // se lea como una sola cadena y no se pierda la mitad.
  let salida = '';
  const re = /<t(?:\s[^>]*)?>([\s\S]*?)<\/t>|<t\s*\/>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(xml)) !== null) salida += desescapar(m[1] ?? '');
  return salida;
}

function cadenasCompartidas(xml: string | null): string[] {
  if (!xml) return [];
  const salida: string[] = [];
  const re = /<si(?:\s[^>]*)?>([\s\S]*?)<\/si>|<si\s*\/>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(xml)) !== null) salida.push(textoDe(m[1] ?? ''));
  return salida;
}

/** "BC12" -> 54. Base 26 sin cero, que es como Excel numera las columnas. */
function columnaDe(referencia: string): number {
  const letras = /^([A-Z]+)/.exec(referencia.toUpperCase())?.[1] ?? 'A';
  let n = 0;
  for (const c of letras) n = n * 26 + (c.charCodeAt(0) - 64);
  return n - 1;
}

/**
 * Reparte el valor de una celda combinada por todo su rango.
 *
 * Excel guarda "ENTRADAS" —el encabezado que abarca de G a K— UNA sola vez, en
 * G, y aparte una nota de que G:K van unidas. Un lector literal ve el texto en
 * G y cuatro celdas vacias a su derecha.
 *
 * Se rellenan las cuatro por dos razones. La primera es que es lo que hace
 * `exceljs`, y de esa coincidencia vive la prueba que respalda todo este
 * lector: si uno rellena y el otro no, no hay forma de compararlos. La
 * segunda es que asi se detectan los encabezados de dos pisos, que es como
 * viene el inventario de la empresa —una fila con "ENTRADAS" y "SALIDA"
 * abarcando grupos, y debajo otra con "cantidad", "fecha", "precio"—. Sin
 * repartir, la columna de la cantidad de SALIDA no tiene forma de saber a que
 * grupo pertenece.
 */
function repartirCombinadas(xml: string, filas: Celda[][]): void {
  for (const m of xml.matchAll(/<mergeCell\s+ref="([A-Z]+)(\d+):([A-Z]+)(\d+)"/g)) {
    const c1 = columnaDe(m[1]!);
    const f1 = Number(m[2]) - 1;
    const c2 = columnaDe(m[3]!);
    const f2 = Number(m[4]) - 1;
    const valor = filas[f1]?.[c1] ?? null;
    if (valor === null) continue;

    for (let f = f1; f <= f2; f += 1) {
      while (filas.length <= f) filas.push([]);
      const fila = filas[f]!;
      for (let c = c1; c <= c2; c += 1) {
        while (fila.length <= c) fila.push(null);
        if (f !== f1 || c !== c1) fila[c] = valor;
      }
    }
  }
}

function celdasDeHoja(xml: string, compartidas: string[]): Celda[][] {
  const filas: Celda[][] = [];
  const reFila = /<row(\s[^>]*)?>([\s\S]*?)<\/row>|<row(\s[^>]*)\/>/g;
  let mf: RegExpExecArray | null;

  while ((mf = reFila.exec(xml)) !== null) {
    const atributosFila = mf[1] ?? mf[3] ?? '';
    const cuerpo = mf[2] ?? '';
    const fila: Celda[] = [];

    // La fila va en SU numero, no en el siguiente hueco del arreglo.
    //
    // Excel no escribe las filas vacias. Empujarlas en orden compacta el
    // archivo: la fila 5 del Excel acaba en la posicion 3, y a partir de ahi
    // todo esta desplazado. Lo caza la prueba que compara con exceljs —el
    // encabezado "PRODUCTOS" salia vacio— y en un importador ese desfase es
    // silencioso y grave: los codigos se leerian de la fila de al lado.
    const numero = Number(/r="(\d+)"/.exec(atributosFila)?.[1] ?? '0');
    const destino = numero > 0 ? numero - 1 : filas.length;
    while (filas.length < destino) filas.push([]);
    const reCelda = /<c\s([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g;
    let mc: RegExpExecArray | null;

    while ((mc = reCelda.exec(cuerpo)) !== null) {
      const atributos = mc[1] ?? '';
      const dentro = mc[2] ?? '';
      const ref = /r="([A-Z]+\d+)"/i.exec(atributos)?.[1] ?? '';
      const tipo = /t="([^"]+)"/.exec(atributos)?.[1] ?? 'n';
      const col = ref ? columnaDe(ref) : fila.length;

      // Las celdas vacias no se escriben en el XML: la columna se deduce de la
      // referencia. Sin esto, una fila con un hueco corre todo a la izquierda
      // y el codigo de un producto acaba en la columna del nombre.
      while (fila.length < col) fila.push(null);

      let valor: Celda = null;
      if (tipo === 's') {
        const i = Number(/<v>([\s\S]*?)<\/v>/.exec(dentro)?.[1] ?? '-1');
        valor = compartidas[i] ?? null;
      } else if (tipo === 'inlineStr') {
        valor = textoDe(dentro);
      } else if (tipo === 'str') {
        valor = desescapar(/<v>([\s\S]*?)<\/v>/.exec(dentro)?.[1] ?? '');
      } else if (tipo === 'b') {
        valor = /<v>1<\/v>/.test(dentro) ? 'VERDADERO' : 'FALSO';
      } else if (tipo === 'e') {
        // #N/A, #REF!… Se conserva el texto del error en vez de fingir que la
        // celda esta vacia: quien revisa tiene que verlo.
        valor = desescapar(/<v>([\s\S]*?)<\/v>/.exec(dentro)?.[1] ?? '');
      } else {
        const crudo = /<v>([\s\S]*?)<\/v>/.exec(dentro)?.[1];
        if (crudo !== undefined && crudo !== '') {
          const n = Number(crudo);
          valor = Number.isFinite(n) ? n : desescapar(crudo);
        }
      }

      if (fila.length === col) fila.push(valor);
      else fila[col] = valor;
    }

    if (filas.length === destino) filas.push(fila);
    else filas[destino] = fila;
  }

  repartirCombinadas(xml, filas);
  return filas;
}

/* ------------------------------------------------------------------ */
/* La puerta                                                           */
/* ------------------------------------------------------------------ */

/**
 * Lee un .xlsx y devuelve sus hojas en el orden del libro.
 *
 * El orden importa: el nombre de la hoja se saca de `workbook.xml`, que es
 * donde esta el que ve el usuario en la pestana. El nombre del archivo interno
 * (`sheet3.xml`) no tiene relacion fiable con la posicion, y ordenar por el
 * mezcla las hojas —que en un inventario significa mezclar divisiones.
 */
export async function leerXlsx(datos: ArrayBuffer): Promise<Hoja[]> {
  const vista = new DataView(datos);
  const entradas = leerTablaDeContenidos(vista);
  const porNombre = new Map(entradas.map((e) => [e.nombre, e]));

  const libroEntrada = porNombre.get('xl/workbook.xml');
  if (!libroEntrada) {
    throw new Error('El archivo no tiene la estructura de un Excel (falta xl/workbook.xml).');
  }
  const libro = await extraer(vista, libroEntrada);

  const relsEntrada = porNombre.get('xl/_rels/workbook.xml.rels');
  const rels = relsEntrada ? await extraer(vista, relsEntrada) : '';
  const destinoDeRel = new Map<string, string>();
  for (const m of rels.matchAll(/<Relationship\s([^>]*)\/?>/g)) {
    const a = m[1] ?? '';
    const id = /Id="([^"]+)"/.exec(a)?.[1];
    const destino = /Target="([^"]+)"/.exec(a)?.[1];
    if (id && destino) destinoDeRel.set(id, destino.replace(/^\/?xl\//, '').replace(/^\//, ''));
  }

  const compartidasEntrada = porNombre.get('xl/sharedStrings.xml');
  const compartidas = cadenasCompartidas(
    compartidasEntrada ? await extraer(vista, compartidasEntrada) : null,
  );

  const hojas: Hoja[] = [];
  for (const m of libro.matchAll(/<sheet\s([^>]*)\/?>/g)) {
    const a = m[1] ?? '';
    const nombre = desescapar(/name="([^"]*)"/.exec(a)?.[1] ?? 'Hoja');
    const rid = /r:id="([^"]+)"/.exec(a)?.[1] ?? '';
    const destino = destinoDeRel.get(rid);
    if (!destino) continue;

    const entrada = porNombre.get(`xl/${destino}`);
    if (!entrada) continue;

    const xml = await extraer(vista, entrada);
    hojas.push({ nombre, filas: celdasDeHoja(xml, compartidas) });
  }

  return hojas;
}

/**
 * Lee un CSV.
 *
 * Se admite porque la mitad de los precios que llegan de un proveedor vienen
 * asi, y porque exportar a CSV es lo que sabe hacer cualquiera cuando el
 * .xlsx da problemas.
 *
 * El separador se DETECTA en vez de suponerse: un CSV guardado en Excel con
 * configuracion de Mexico usa coma, y el mismo Excel con configuracion de
 * Espana usa punto y coma. Suponer coma parte "1.234,50" en dos columnas.
 */
export function leerCsv(texto: string, nombre = 'CSV'): Hoja {
  const limpio = texto.replace(/^﻿/, '');
  const primera = limpio.split(/\r?\n/, 1)[0] ?? '';
  const fuera = primera.replace(/"[^"]*"/g, '');
  const separador = (fuera.match(/;/g)?.length ?? 0) > (fuera.match(/,/g)?.length ?? 0)
    ? ';'
    : ',';

  const filas: Celda[][] = [];
  let fila: Celda[] = [];
  let campo = '';
  let entreComillas = false;

  const empujar = (): void => {
    const t = campo.trim();
    if (t === '') fila.push(null);
    else {
      const n = Number(t.replace(/\s/g, '').replace(/,(\d{1,2})$/, '.$1'));
      fila.push(/^[-+]?[\d.,\s]+$/.test(t) && Number.isFinite(n) ? n : campo.trim());
    }
    campo = '';
  };

  for (let i = 0; i < limpio.length; i += 1) {
    const c = limpio[i]!;
    if (entreComillas) {
      if (c === '"') {
        if (limpio[i + 1] === '"') { campo += '"'; i += 1; } else entreComillas = false;
      } else campo += c;
      continue;
    }
    if (c === '"') { entreComillas = true; continue; }
    if (c === separador) { empujar(); continue; }
    if (c === '\r') continue;
    if (c === '\n') {
      empujar();
      filas.push(fila);
      fila = [];
      continue;
    }
    campo += c;
  }
  if (campo !== '' || fila.length > 0) { empujar(); filas.push(fila); }

  return { nombre, filas };
}

/** Lee lo que sea: .xlsx por su firma de ZIP, y si no, CSV. */
export async function leerLibro(datos: ArrayBuffer, nombre = 'archivo'): Promise<Hoja[]> {
  const bytes = new Uint8Array(datos);
  // "PK": la firma de un ZIP. Se mira el contenido y no la extension, porque
  // un archivo renombrado a .csv sigue siendo un .xlsx y al reves.
  const esZip = bytes[0] === 0x50 && bytes[1] === 0x4b;
  if (esZip) return leerXlsx(datos);
  return [leerCsv(new TextDecoder().decode(bytes), nombre)];
}
