/**
 * Carga inteligente: un archivo entra, un lote de propuestas sale.
 *
 * QUE HACE ESTA PANTALLA, EN UNA FRASE
 *
 * Lee un Excel o un CSV en el navegador, ensena lo que entendio con su nivel
 * de confianza fila por fila, deja corregir lo que interpreto mal, y solo
 * entonces manda el lote a la cola de autorizacion.
 *
 * DONDE ESTA LA "INTELIGENCIA", Y DONDE NO
 *
 * No hay ningun modelo de lenguaje detras. No es una carencia: ninguna clave
 * de API puede estar en el panel —es una regla del proyecto—, y sobre todo la
 * pregunta importante no es si el programa parece listo, sino quien responde
 * de lo que entra al catalogo. Lo que hay es reconocimiento de encabezados,
 * normalizacion, deteccion de repetidos y una puntuacion de confianza que se
 * ENSENA. Todo deterministico y explicable: cada decision se puede senalar.
 *
 * Un importador que acierta el 95% sin decir cual 5% falla es peor que uno que
 * acierta el 80% y senala las dudas. El primero mete basura invisible en el
 * catalogo contra el que se compara TODA salida futura.
 *
 * LO QUE ESTA PANTALLA NO PUEDE HACER
 *
 * Crear un producto. Ni uno. Lo que manda son PROPUESTAS, las mismas que manda
 * un telefono, y hasta que alguien las apruebe en "Productos por aprobar" el
 * inventario no cambia. Por eso descartar una carga no borra nada: no hay nada
 * que borrar.
 */

import { useEffect, useMemo, useRef, useState } from 'react';
import { supabase } from './supabase.ts';
import {
  Tarjeta, Boton, Campo, Selector, Aviso, Cargando, colores, radios, rotulo,
} from './ui.tsx';
import { leerLibro, type Hoja } from '../../../packages/shared/src/xlsx.ts';
import {
  detectarEncabezado, interpretar, resumir,
  type Campo as CampoImp, type FilaImportacion, type MapaColumnas,
} from '../../../packages/shared/src/importador.ts';

const NOMBRES_CAMPO: Record<CampoImp, string> = {
  codigo: 'Código',
  nombre: 'Nombre',
  unidad: 'Unidad',
  cantidad: 'Cantidad',
  precio: 'Precio',
};

const COLOR_CONFIANZA: Record<string, string> = {
  ALTA: '#0E7A4A',
  MEDIA: '#9A6700',
  BAJA: '#B42318',
};

interface Lote {
  id: string;
  label: string;
  source_name: string | null;
  rows_total: number;
  rows_proposed: number;
  rows_skipped: number;
  created_at: string;
  discarded_at: string | null;
  created_by_name: string | null;
  pendientes: number;
  aprobadas: number;
  rechazadas: number;
}

export function CargaInteligente({
  division,
  unidades,
  alCargar,
}: {
  division: string;
  unidades: { code: string; name: string }[];
  alCargar: () => void;
}) {
  const [hojas, setHojas] = useState<Hoja[] | null>(null);
  const [nombreArchivo, setNombreArchivo] = useState('');
  const [iHoja, setIHoja] = useState(0);
  const [mapa, setMapa] = useState<MapaColumnas | null>(null);
  const [unidadPorOmision, setUnidadPorOmision] = useState('');
  const [codigosExistentes, setCodigos] = useState<Set<string> | null>(null);
  const [excluidas, setExcluidas] = useState<Set<number>>(new Set());
  const [aviso, setAviso] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [trabajando, setTrabajando] = useState(false);
  const [lotes, setLotes] = useState<Lote[] | null>(null);
  const [recarga, setRecarga] = useState(0);
  const entrada = useRef<HTMLInputElement>(null);

  /* --- lo que ya existe, para no proponerlo otra vez --- */
  useEffect(() => {
    let vivo = true;
    setCodigos(null);
    supabase()
      .from('admin_catalog')
      .select('code')
      .eq('business_unit', division)
      .then(({ data, error: e }) => {
        if (!vivo) return;
        if (e) {
          setError(e.message);
          return;
        }
        // Se normaliza igual que el importador: mayusculas y espacios
        // colapsados. Si no coincidiera el normalizado, un codigo que ya existe
        // se propondria como nuevo y chocaria al aprobar.
        setCodigos(new Set(
          (data ?? []).map((p) => String((p as { code: unknown }).code)
            .trim().replace(/\s+/g, ' ').toUpperCase()),
        ));
      });
    return () => {
      vivo = false;
    };
  }, [division]);

  /* --- los lotes de antes --- */
  useEffect(() => {
    let vivo = true;
    supabase()
      .from('import_batches_view')
      .select('*')
      .eq('business_unit', division)
      .order('created_at', { ascending: false })
      .limit(20)
      .then(({ data, error: e }) => {
        if (!vivo) return;
        if (e) setError(e.message);
        else setLotes((data ?? []) as unknown as Lote[]);
      });
    return () => {
      vivo = false;
    };
  }, [division, recarga]);

  async function alElegirArchivo(archivo: File): Promise<void> {
    setError(null);
    setAviso(null);
    setExcluidas(new Set());
    try {
      const bytes = await archivo.arrayBuffer();
      const leidas = await leerLibro(bytes, archivo.name);
      // Se queda la hoja con mas filas, no la primera. La primera suele ser una
      // portada con el logo y cuatro celdas.
      let mejor = 0;
      leidas.forEach((h, i) => {
        if (h.filas.length > (leidas[mejor]?.filas.length ?? 0)) mejor = i;
      });
      setHojas(leidas);
      setNombreArchivo(archivo.name);
      setIHoja(mejor);
      setMapa(detectarEncabezado(leidas[mejor]!));
    } catch (causa) {
      setHojas(null);
      setError(causa instanceof Error ? causa.message : String(causa));
    }
  }

  function cambiarHoja(i: number): void {
    setIHoja(i);
    setExcluidas(new Set());
    if (hojas?.[i]) setMapa(detectarEncabezado(hojas[i]!));
  }

  function cambiarColumna(campo: CampoImp, valor: string): void {
    if (!mapa) return;
    setMapa({
      ...mapa,
      columnas: { ...mapa.columnas, [campo]: valor === '' ? null : Number(valor) },
      // Al elegir a mano, la duda desaparece: lo dijo una persona.
      origen: {
        ...mapa.origen,
        [campo]: valor === ''
          ? null
          : { encabezado: mapa.encabezados[Number(valor)] ?? '', exacto: true },
      },
      motivos: [],
      confianza: 'ALTA',
    });
  }

  const hoja = hojas?.[iHoja] ?? null;

  const filas = useMemo<FilaImportacion[]>(() => {
    if (!hoja || !mapa || !codigosExistentes) return [];
    return interpretar(hoja, mapa, {
      codigosExistentes,
      unidades: new Set(unidades.map((u) => u.code.toUpperCase())),
      unidadPorOmision: unidadPorOmision === '' ? null : unidadPorOmision,
    });
  }, [hoja, mapa, codigosExistentes, unidades, unidadPorOmision]);

  const resumen = useMemo(() => resumir(filas), [filas]);

  /** Las que se van a mandar: las de CREAR que nadie haya destildado. */
  const aMandar = filas.filter((f) => f.accion === 'CREAR' && !excluidas.has(f.fila));

  async function mandar(): Promise<void> {
    setTrabajando(true);
    setAviso(null);
    setError(null);

    const { data, error: e } = await supabase().rpc('app_import_proposals', {
      p_business_unit: division,
      p_source_name: `${nombreArchivo} · ${hoja?.nombre ?? ''}`,
      p_items: aMandar.map((f) => ({
        code: f.codigo,
        name: f.nombre,
        unit_code: f.unidad,
        quantity: f.cantidad,
        notes: `Cargado de ${nombreArchivo}, fila ${f.fila}.`,
      })),
    });

    setTrabajando(false);
    const r = data as { outcome: string; message?: string } | null;
    if (e || r?.outcome !== 'DONE') {
      setError(e?.message ?? r?.message ?? 'No se pudo cargar el archivo.');
      return;
    }
    setAviso(r.message ?? 'Cargado.');
    setHojas(null);
    setMapa(null);
    setNombreArchivo('');
    if (entrada.current) entrada.current.value = '';
    setRecarga((n) => n + 1);
    alCargar();
  }

  async function descartar(lote: Lote): Promise<void> {
    setTrabajando(true);
    setError(null);
    const { data, error: e } = await supabase().rpc('app_discard_import', {
      p_batch_id: lote.id,
      p_reason: null,
    });
    setTrabajando(false);
    const r = data as { outcome: string; message?: string } | null;
    if (e || r?.outcome !== 'APPLIED') {
      setError(e?.message ?? r?.message ?? 'No se pudo descartar.');
      return;
    }
    setAviso(r.message ?? 'Descartado.');
    setRecarga((n) => n + 1);
    alCargar();
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <Tarjeta>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 18 }}>
          <div>
            <span style={rotulo}>Carga inteligente</span>
            <h2 style={{ margin: '2px 0 0' }}>Un archivo, revisado antes de entrar</h2>
            <p style={{ margin: '6px 0 0', fontSize: 14, color: colores.tintaTenue, maxWidth: 760 }}>
              Excel o CSV. Se lee <strong>en este navegador</strong> —el archivo no se sube a
              ninguna parte— y se enseña lo que se entendió con su nivel de confianza. Lo que
              se manda son <strong>propuestas</strong>: nada entra al inventario hasta que alguien
              las apruebe en «Productos por aprobar», y por eso una carga se puede descartar sin
              que el inventario haya cambiado en ningún momento.
            </p>
          </div>

          <div>
            <input
              ref={entrada}
              type="file"
              accept=".xlsx,.csv,.txt"
              onChange={(ev) => {
                const f = ev.target.files?.[0];
                if (f) void alElegirArchivo(f);
              }}
              style={{ fontSize: 15 }}
            />
          </div>

          {error && <Aviso>{error}</Aviso>}
          {aviso && <Aviso>{aviso}</Aviso>}

          {hojas && hoja && mapa && (
            <>
              {hojas.length > 1 && (
                <div style={{ maxWidth: 320 }}>
                  <Selector
                    etiqueta="Hoja"
                    valor={String(iHoja)}
                    alCambiar={(v) => cambiarHoja(Number(v))}
                    opciones={hojas.map((h, i) => ({
                      valor: String(i),
                      texto: `${h.nombre} · ${h.filas.length} filas`,
                    }))}
                  />
                </div>
              )}

              {/* El mapa de columnas, siempre visible y siempre editable.
                  Esconderlo cuando la deteccion parece segura es lo que
                  permite que un catalogo entero entre indexado por la columna
                  equivocada sin que nadie lo vea. */}
              <div>
                <span style={rotulo}>Qué es cada columna</span>
                <p style={{ margin: '4px 0 10px', fontSize: 13, color: colores.tintaTenue }}>
                  Encabezado detectado en la fila {mapa.filaEncabezado}. Corrija lo que haga falta.
                </p>
                <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                  {(Object.keys(NOMBRES_CAMPO) as CampoImp[]).map((campo) => (
                    <div key={campo} style={{ flex: '1 1 170px' }}>
                      <Selector
                        etiqueta={NOMBRES_CAMPO[campo]}
                        valor={mapa.columnas[campo] === null ? '' : String(mapa.columnas[campo])}
                        alCambiar={(v) => cambiarColumna(campo, v)}
                        opciones={[
                          { valor: '', texto: '— ninguna —' },
                          ...mapa.encabezados.map((h, i) => ({
                            valor: String(i),
                            texto: `${letraColumna(i)} · ${h || '(vacío)'}`,
                          })),
                        ]}
                      />
                      {mapa.origen[campo] && !mapa.origen[campo]!.exacto && (
                        <span style={{ fontSize: 12, color: COLOR_CONFIANZA['BAJA'] }}>
                          Solo se parece. Confírmelo.
                        </span>
                      )}
                    </div>
                  ))}
                  <div style={{ flex: '1 1 170px' }}>
                    <Selector
                      etiqueta="Unidad si falta"
                      valor={unidadPorOmision}
                      alCambiar={setUnidadPorOmision}
                      opciones={[
                        { valor: '', texto: '— no suponer —' },
                        ...unidades.map((u) => ({ valor: u.code, texto: `${u.code} · ${u.name}` })),
                      ]}
                    />
                  </div>
                </div>
              </div>

              {mapa.motivos.length > 0 && (
                <Aviso>{mapa.motivos.join(' ')}</Aviso>
              )}

              {/* Las cuentas ANTES de mandar nada. */}
              <div style={{ display: 'flex', gap: 22, flexWrap: 'wrap', alignItems: 'baseline' }}>
                <Cuenta n={resumen.crear} texto="se pueden dar de alta" tono="#0E7A4A" />
                <Cuenta n={resumen.revisar} texto="necesitan que decida usted" tono="#9A6700" />
                <Cuenta n={resumen.yaExisten} texto="ya están en el catálogo" tono={colores.tintaTenue} />
                <Cuenta n={resumen.repetidas} texto="repetidas en el archivo" tono="#B42318" />
                <Cuenta
                  n={resumen.conCantidad}
                  texto={`traen existencia (${resumen.unidadesTotales} en total)`}
                  tono={colores.tintaTenue}
                />
              </div>

              <TablaFilas
                filas={filas}
                excluidas={excluidas}
                alternar={(f) => setExcluidas((p) => {
                  const s = new Set(p);
                  if (s.has(f)) s.delete(f);
                  else s.add(f);
                  return s;
                })}
              />

              <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' }}>
                <Boton
                  tono="marca"
                  disabled={trabajando || aMandar.length === 0}
                  onClick={() => void mandar()}
                >
                  {trabajando
                    ? 'Cargando…'
                    : `Mandar ${aMandar.length} a autorización`}
                </Boton>
                <span style={{ fontSize: 13, color: colores.tintaTenue }}>
                  Después hay que aprobarlas en «Productos por aprobar». Hasta entonces el
                  inventario no cambia.
                </span>
              </div>
            </>
          )}
        </div>
      </Tarjeta>

      {/* --- las cargas de antes --- */}
      <Tarjeta>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <div>
            <span style={rotulo}>Cargas anteriores</span>
            <p style={{ margin: '4px 0 0', fontSize: 13, color: colores.tintaTenue }}>
              Descartar una carga rechaza sus propuestas pendientes. No borra movimientos ni
              existencias, porque nunca los creó.
            </p>
          </div>

          {lotes === null ? (
            <Cargando />
          ) : lotes.length === 0 ? (
            <Aviso>Todavía no se ha cargado ningún archivo en esta división.</Aviso>
          ) : (
            lotes.map((l) => (
              <div
                key={l.id}
                style={{
                  display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center',
                  justifyContent: 'space-between', padding: '11px 15px',
                  borderRadius: radios.md, border: `1px solid ${colores.linea}`,
                  background: l.discarded_at ? 'transparent' : colores.papel,
                  opacity: l.discarded_at ? 0.6 : 1,
                }}
              >
                <span>
                  <strong style={{ fontSize: 15 }}>{l.label}</strong>{' '}
                  <span style={{ fontSize: 13, color: colores.tintaTenue }}>
                    {l.source_name ?? 'sin nombre de archivo'} ·{' '}
                    {l.rows_proposed} propuestas, {l.rows_skipped} apartadas ·{' '}
                    {l.pendientes} pendientes, {l.aprobadas} aprobadas, {l.rechazadas} rechazadas ·{' '}
                    {l.created_by_name ?? '—'} ·{' '}
                    {new Date(l.created_at).toLocaleString('es-MX', {
                      day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit',
                    })}
                    {l.discarded_at ? ' · descartada' : ''}
                  </span>
                </span>
                {l.pendientes > 0 && (
                  <Boton disabled={trabajando} onClick={() => void descartar(l)}>
                    Descartar {l.pendientes} pendientes
                  </Boton>
                )}
              </div>
            ))
          )}
        </div>
      </Tarjeta>
    </div>
  );
}

/** "A", "B"… "AA". La letra que la persona ve en Excel. */
function letraColumna(i: number): string {
  let n = i + 1;
  let s = '';
  while (n > 0) {
    const r = (n - 1) % 26;
    s = String.fromCharCode(65 + r) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

function Cuenta({ n, texto, tono }: { n: number; texto: string; tono: string }) {
  return (
    <span style={{ display: 'inline-flex', alignItems: 'baseline', gap: 6 }}>
      <strong style={{ fontSize: 26, color: tono, fontVariantNumeric: 'tabular-nums' }}>{n}</strong>
      <span style={{ fontSize: 13, color: colores.tintaTenue }}>{texto}</span>
    </span>
  );
}

/**
 * La tabla de revision.
 *
 * Ordenada por lo que hay que MIRAR, no por el numero de fila: las que
 * necesitan una decision primero. Con doscientas filas, ordenarlas por su
 * posicion en el Excel entierra las siete que importan.
 */
function TablaFilas({
  filas, excluidas, alternar,
}: {
  filas: FilaImportacion[];
  excluidas: Set<number>;
  alternar: (fila: number) => void;
}) {
  const orden: Record<string, number> = { REVISAR: 0, CREAR: 1, OMITIR: 2 };
  const ordenadas = [...filas].sort(
    (a, b) => (orden[a.accion] ?? 9) - (orden[b.accion] ?? 9) || a.fila - b.fila,
  );

  return (
    <div style={{ overflowX: 'auto', maxHeight: 460, overflowY: 'auto' }}>
      <table style={{ borderCollapse: 'collapse', width: '100%', fontSize: 14 }}>
        <thead>
          <tr>
            {['', 'Fila', 'Código', 'Nombre', 'Unidad', 'Cant.', 'Qué pasa'].map((h) => (
              <th
                key={h}
                style={{
                  textAlign: 'left', padding: '7px 10px', position: 'sticky', top: 0,
                  background: colores.papel, borderBottom: `1px solid ${colores.lineaFuerte}`,
                  ...rotulo,
                }}
              >
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {ordenadas.map((f) => (
            <tr key={f.fila} style={{ borderBottom: `1px solid ${colores.linea}` }}>
              <td style={{ padding: '6px 10px' }}>
                {f.accion === 'CREAR' && (
                  <input
                    type="checkbox"
                    checked={!excluidas.has(f.fila)}
                    onChange={() => alternar(f.fila)}
                    aria-label={`Incluir ${f.codigo}`}
                    style={{ width: 17, height: 17 }}
                  />
                )}
              </td>
              <td style={{ padding: '6px 10px', color: colores.tintaTenue }}>{f.fila}</td>
              <td style={{ padding: '6px 10px' }}>
                <code>{f.codigo || '—'}</code>
              </td>
              <td style={{ padding: '6px 10px', maxWidth: 300 }}>{f.nombre || '—'}</td>
              <td style={{ padding: '6px 10px' }}>{f.unidad ?? '—'}</td>
              <td style={{ padding: '6px 10px', textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                {f.cantidad ?? ''}
              </td>
              <td style={{ padding: '6px 10px' }}>
                <span
                  style={{
                    fontSize: 11, fontWeight: 700, letterSpacing: 0.5,
                    color: COLOR_CONFIANZA[f.confianza],
                  }}
                >
                  {f.accion}
                </span>
                {f.motivos.length > 0 && (
                  <div style={{ fontSize: 12, color: colores.tintaTenue }}>
                    {f.motivos.join(' ')}
                  </div>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
