/**
 * El muestrario: todas las piezas de la interfaz, juntas y sin entrar.
 *
 * PARA QUE SIRVE
 *
 * Se abre con `?muestrario` al final de la direccion del panel. No pide
 * contrasena y no toca la base: pinta cada componente con datos de mentira.
 *
 * POR QUE HIZO FALTA
 *
 * Para cambiar el aspecto de algo hay que poder MIRARLO, y todo lo que se ve en
 * este panel esta detras de la entrada. Al ajustar la presentacion siguiendo la
 * del hub de Grupo Manantial me encontre editando pantallas que no podia abrir
 * —no tengo credenciales— y comprobando el resultado leyendo el codigo, que es
 * exactamente como se cuelan los fallos de aspecto: el codigo puede estar bien y
 * la pantalla verse mal.
 *
 * Tambien sirve despues: es donde se ve de un golpe si una pieza nueva pega con
 * las demas, y donde se prueban los estados raros —el cero, el numero larguisimo,
 * el nombre que no cabe— que en la base casi nunca aparecen a la vez.
 *
 * NO ENTRA EN EL PROGRAMA QUE USA LA GENTE salvo que se pida por la direccion.
 */

import {
  Tarjeta, Boton, Campo, Selector, SenalStock, Aviso, Error as Alerta, Cargando,
  colores, radios, letra, rotulo, Firma, Interruptor, Pulso,
  TituloDePagina, Insignia, estados, type Estado,
} from './ui.tsx';
import { useState } from 'react';

function Bloque({ nombre, nota, children }: {
  nombre: string; nota?: string; children: React.ReactNode;
}) {
  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <div>
        <div style={rotulo}>{nombre}</div>
        {nota && (
          <p style={{ margin: '4px 0 0', fontSize: 13, color: colores.tintaTenue, maxWidth: '64ch' }}>
            {nota}
          </p>
        )}
      </div>
      <Tarjeta style={{ display: 'flex', flexWrap: 'wrap', gap: 14, alignItems: 'center' }}>
        {children}
      </Tarjeta>
    </section>
  );
}

export function Muestrario() {
  const [texto, setTexto] = useState('PERFIL-40X60');
  const [clave, setClave] = useState('algo escrito');
  const [unidad, setUnidad] = useState('PZA');
  const [encendido, setEncendido] = useState(true);

  return (
    <div style={{
      maxWidth: 1000, margin: '0 auto', padding: '32px 24px 80px',
      display: 'flex', flexDirection: 'column', gap: 34,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 16, flexWrap: 'wrap' }}>
        <Firma ancho={92} />
        <div style={{ flex: 1, minWidth: 220 }}>
          <TituloDePagina sub={
            <>Todas las piezas de la interfaz, con datos de mentira. No toca la base y no
            hace falta entrar. Se abre añadiendo <code>?muestrario</code> a la dirección.</>
          }>
            Muestrario
          </TituloDePagina>
        </div>
        <Pulso conectado />
      </div>

      <Bloque
        nombre="Encabezado de pantalla"
        nota={'La forma en que presenta sus pantallas el resto de la empresa: el nombre, y '
          + 'debajo una frase que dice para qué sirve y qué pasa después. Si la frase no '
          + 'añade nada al título, es mejor no ponerla.'}
      >
        <div style={{ width: '100%' }}>
          <TituloDePagina sub={
            <>Lo que hay ahora mismo en el almacén de Cancelería. Se actualiza solo con cada
            entrada y cada salida que registra el teléfono; lo escaso sube al principio.</>
          }>
            Inventario
          </TituloDePagina>
        </div>
      </Bloque>

      <Bloque
        nombre="Estados"
        nota={'En pastilla, como en el hub: el color con significado al 15 % de fondo y ese '
          + 'mismo color, más vivo, en el texto. Los cuatro son los de la empresa (--ok, '
          + '--warn, --danger, --info), aclarados para que se lean sobre oscuro.'}
      >
        {(Object.keys(estados) as Estado[]).map((e) => (
          <Insignia key={e} estado={e}>{e}</Insignia>
        ))}
      </Bloque>

      <Bloque
        nombre="Señal de existencia"
        nota={'Lleva icono además del color: una de cada doce personas no distingue bien el '
          + 'rojo del verde, y aquí lo único que separaría «Agotado» de «Suficiente» sería '
          + 'el color.'}
      >
        <SenalStock cantidad={0} minimo={5} />
        <SenalStock cantidad={3} minimo={5} />
        <SenalStock cantidad={40} minimo={5} />
        <SenalStock cantidad={7} minimo={null} />
      </Bloque>

      <Bloque nombre="Botones" nota="El relleno de marca es el que hace algo; el neutro es un contorno.">
        <Boton tono="marca">Guardar</Boton>
        <Boton>Cancelar</Boton>
        <Boton tono="aprobar">Aprobar</Boton>
        <Boton tono="rechazar">Rechazar</Boton>
        <Boton tono="marca" disabled>Sin poder</Boton>
      </Bloque>

      <Bloque
        nombre="Campos"
        nota={'El de contraseña lleva el botón de mirar a lo alto entero del campo. El del hub '
          + 'mide 16×16 px, menos de la mitad del mínimo táctil.'}
      >
        <div style={{ display: 'grid', gap: 14, gridTemplateColumns: 'repeat(auto-fit,minmax(230px,1fr))', width: '100%' }}>
          <Campo etiqueta="Código" valor={texto} alCambiar={setTexto} />
          <Campo etiqueta="Contraseña" valor={clave} alCambiar={setClave} tipo="password" revelable />
          <Selector
            etiqueta="Unidad" valor={unidad} alCambiar={setUnidad}
            opciones={[
              { valor: 'PZA', texto: 'Pieza' },
              { valor: 'MTS', texto: 'Metro' },
              { valor: 'KG', texto: 'Kilogramo' },
            ]}
          />
          <Campo
            etiqueta="Mínimo" valor="5" alCambiar={() => {}} tipo="number"
            ayuda="Por debajo de esto, el producto sube al principio del inventario."
          />
        </div>
      </Bloque>

      <Bloque nombre="Interruptor">
        <Interruptor encendido={encendido} alCambiar={setEncendido}>
          Solo lo que está por debajo del mínimo
        </Interruptor>
      </Bloque>

      <Bloque nombre="Mensajes" nota="El aviso advierte de algo cierto; el error dice qué salió mal.">
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, width: '100%' }}>
          <Aviso>
            Mientras una salida esté aquí, el material <strong>ya salió físicamente</strong> y la
            existencia ya lo refleja.
          </Aviso>
          <Alerta>
            Sin conexión con la base central. Lo que ve en pantalla puede estar desactualizado.
            Se vuelve a intentar solo en cuanto haya red; no hace falta recargar.
          </Alerta>
          <Alerta>La unidad &quot;PZA 1&quot; no existe en el catálogo.</Alerta>
        </div>
      </Bloque>

      <Bloque nombre="Espera">
        <Cargando texto="Buscando salidas pendientes…" />
      </Bloque>

      <Bloque
        nombre="Tabla"
        nota={'Rótulos en versalitas pequeñas y cifras alineadas por la derecha con figuras de '
          + 'ancho fijo, para que las columnas de números se lean como una columna.'}
      >
        <div style={{ overflowX: 'auto', width: '100%' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: `2px solid ${colores.linea}`, textAlign: 'left' }}>
                {['Código', 'Producto', 'Unidad', 'Existencia', 'Estado'].map((h, i) => (
                  <th key={h} style={{ ...rotulo, padding: '14px 14px 10px', textAlign: i === 3 ? 'right' : 'left' }}>
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {[
                ['PERFIL-40X60', 'Perfil de PVC blanco 40×60', 'MTS', 0, 5],
                ['SILICON-NEUTRO', 'Silicón neutro transparente', 'PZA', 3, 5],
                ['TORNILLO-8X1', 'Tornillo autoperforante 8×1"', 'PZA', 1240, 100],
                ['NOMBRE-MUY-LARGO-QUE-NO-CABE', 'Un nombre deliberadamente largo para ver qué pasa cuando no cabe en la columna', 'PZA', 12, null],
              ].map(([cod, nom, un, cant, min]) => (
                <tr key={cod as string} style={{ borderBottom: `1px solid ${colores.linea}` }}>
                  <td style={{ padding: '13px 14px', fontSize: 13, fontFamily: 'ui-monospace, monospace' }}>{cod}</td>
                  <td style={{ padding: '13px 14px', fontSize: 14 }}>{nom}</td>
                  <td style={{ padding: '13px 14px', fontSize: 14, color: colores.tintaTenue }}>{un}</td>
                  <td style={{
                    padding: '13px 14px', fontSize: 14, textAlign: 'right',
                    fontVariantNumeric: 'tabular-nums',
                  }}>
                    {cant as number}
                  </td>
                  <td style={{ padding: '13px 14px' }}>
                    <SenalStock cantidad={cant as number} minimo={min as number | null} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Bloque>

      <Bloque nombre="Tipografía">
        <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 10 }}>
          <div style={{ fontFamily: letra.serif, fontSize: 30 }}>Inventarios Luft</div>
          <div style={{ fontSize: 24, fontWeight: 700, letterSpacing: '-0.02em' }}>
            Título de pantalla · 24 / 700 / −0.02em
          </div>
          <div style={{ fontSize: 14, color: colores.tintaTenue }}>
            Frase que explica · 14 / 400 / tinta tenue
          </div>
          <div style={rotulo}>Rótulo · 11 / 600 / 0.18em</div>
          <div style={{ fontSize: 13, color: colores.tintaDebil }}>Letra menuda · 13</div>
        </div>
      </Bloque>

      <Bloque nombre="Radios y color">
        {([['sm', radios.sm], ['md', radios.md], ['lg', radios.lg]] as const).map(([n, r]) => (
          <div key={n} style={{
            width: 88, height: 66, borderRadius: r, background: colores.superficieAlta,
            border: `1px solid ${colores.lineaFuerte}`, display: 'grid', placeItems: 'center',
            fontSize: 12, color: colores.tintaTenue,
          }}>
            {n} · {r}
          </div>
        ))}
        {[['marca', colores.marca], ['tinta', colores.tinta], ['tenue', colores.tintaTenue],
          ['aprobar', colores.aprobar], ['rechazar', colores.rechazar]].map(([n, c]) => (
          <div key={n as string} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <span style={{
              width: 26, height: 26, borderRadius: 8, background: c as string,
              border: `1px solid ${colores.linea}`,
            }} />
            <span style={{ fontSize: 12, color: colores.tintaTenue }}>{n}</span>
          </div>
        ))}
      </Bloque>
    </div>
  );
}
