/**
 * Normalizacion de datos capturados a mano.
 *
 * Principio rector: normalizar NUNCA destruye informacion. El valor original se
 * conserva siempre; lo que producen estas funciones es una *clave de resolucion*
 * o un valor tipado, mas un registro de que se cambio.
 *
 * Ver docs/MIGRATION.md seccion 5 para el porque de cada regla.
 */

/** Caracteres invisibles que aparecen al pegar desde Excel, web o PDF. */
const INVISIBLE_CHARS = /[ ​‌‍⁠﻿]/g;

/** Espacios internos repetidos (incluye tabs y saltos). */
const COLLAPSIBLE_WHITESPACE = /\s+/g;

/**
 * Convierte un valor de celda a texto sin notacion cientifica ni `.0` espurio.
 *
 * Excel entrega los codigos numericos como `number`, de modo que `111393171`
 * llega como `111393171` y `7260823607` puede imprimirse como `7.260823607e+9`.
 * Ambas formas deben producir la misma cadena de digitos.
 */
export function cellToText(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'boolean') return value ? 'TRUE' : 'FALSE';
  if (value instanceof Date) return value.toISOString();

  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return '';
    if (Number.isInteger(value)) {
      // BigInt evita cualquier notacion cientifica para enteros grandes.
      return BigInt(value).toString();
    }
    // No entero: se conserva tal cual, sin redondear.
    return String(value);
  }

  if (typeof value === 'bigint') return value.toString();
  return String(value);
}

/**
 * Clave de resolucion de un codigo de producto.
 *
 * Se conservan guiones, barras, comas y puntos: son parte legitima del codigo
 * (`801-947/0004`, `BF-1112S,N`, `CO-1811 S 90`).
 */
export function normalizeCode(raw: unknown): string {
  return cellToText(raw)
    .replace(INVISIBLE_CHARS, '')
    .trim()
    .replace(COLLAPSIBLE_WHITESPACE, ' ')
    .toUpperCase();
}

/**
 * Limpieza de una descripcion. NO cambia mayusculas ni acentos: la diferencia
 * entre `SILICON NEGRO` y `Silicon negro` es informacion que el administrador
 * debe ver, no algo que el sistema deba aplanar.
 */
export function normalizeDescription(raw: unknown): string {
  return cellToText(raw)
    .replace(INVISIBLE_CHARS, '')
    .trim()
    .replace(COLLAPSIBLE_WHITESPACE, ' ');
}

/**
 * Clave de comparacion difusa entre descripciones, usada SOLO para *sugerir*
 * posibles duplicados en la pantalla de conflictos. Nunca para fusionar.
 */
export function descriptionMatchKey(raw: unknown): string {
  return normalizeDescription(raw)
    .toUpperCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '') // quita acentos
    .replace(/[^A-Z0-9]/g, '');      // quita puntuacion y espacios
}

export type ParseResult<T> =
  | { ok: true; value: T; corrected: boolean; note?: string }
  | { ok: false; raw: string; reason: string };

/**
 * Convierte una cantidad capturada a numero.
 *
 * Acepta coma decimal (`"1,5"` -> 1.5), que aparece en el Excel origen.
 * Rechaza vacio y no numerico: devolver 0 seria inventar un dato.
 */
export function parseQuantity(raw: unknown): ParseResult<number> {
  if (typeof raw === 'number') {
    if (!Number.isFinite(raw)) return { ok: false, raw: String(raw), reason: 'CANTIDAD_NO_FINITA' };
    return { ok: true, value: raw, corrected: false };
  }

  const text = cellToText(raw).replace(INVISIBLE_CHARS, '').trim();
  if (text === '') return { ok: false, raw: '', reason: 'CANTIDAD_VACIA' };

  // Separador de miles con espacio: "1 000" -> "1000"
  const withoutThousandSpaces = text.replace(/(?<=\d)[  ](?=\d{3}\b)/g, '');
  const hasComma = withoutThousandSpaces.includes(',');
  const candidate = hasComma ? withoutThousandSpaces.replace(',', '.') : withoutThousandSpaces;

  if (!/^-?\d+(\.\d+)?$/.test(candidate)) {
    return { ok: false, raw: text, reason: 'CANTIDAD_NO_NUMERICA' };
  }

  const value = Number(candidate);
  if (!Number.isFinite(value)) return { ok: false, raw: text, reason: 'CANTIDAD_NO_FINITA' };

  return hasComma
    ? { ok: true, value, corrected: true, note: `coma decimal normalizada desde "${text}"` }
    : { ok: true, value, corrected: text !== candidate };
}

/**
 * Convierte una fecha capturada a `Date`.
 *
 * Deliberadamente NO interpreta texto como `abr`, `27-juli` o `30-juli`: no hay
 * forma de deducir el anio sin inventarlo. Devuelve `ok:false` con el texto
 * literal para que quede en la cola de revision administrativa.
 */
export function parseDate(raw: unknown): ParseResult<Date> {
  if (raw instanceof Date) {
    if (Number.isNaN(raw.getTime())) return { ok: false, raw: String(raw), reason: 'FECHA_INVALIDA' };
    return { ok: true, value: raw, corrected: false };
  }

  const text = cellToText(raw).replace(INVISIBLE_CHARS, '').trim();
  if (text === '') return { ok: false, raw: '', reason: 'FECHA_VACIA' };

  // Solo se acepta ISO completo e inequivoco: YYYY-MM-DD [THH:mm...]
  const iso = /^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$/.exec(text);
  if (iso) {
    const parsed = new Date(text.includes('T') ? text : `${text}T00:00:00.000Z`);
    if (!Number.isNaN(parsed.getTime())) return { ok: true, value: parsed, corrected: false };
  }

  return { ok: false, raw: text, reason: 'FECHA_AMBIGUA' };
}

/**
 * Distancia de Levenshtein acotada, para busqueda tolerante a errores de
 * escritura (`junquiyo` -> `Junquillo`) y sugerencia de duplicados.
 *
 * Corta en cuanto supera `maxDistance` para no gastar tiempo en pares lejanos.
 */
export function levenshtein(a: string, b: string, maxDistance = Infinity): number {
  if (a === b) return 0;
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;
  if (Math.abs(a.length - b.length) > maxDistance) return maxDistance + 1;

  let previous = Array.from({ length: b.length + 1 }, (_, i) => i);
  let current = new Array<number>(b.length + 1);

  for (let i = 1; i <= a.length; i++) {
    current[0] = i;
    let rowMin = current[0]!;
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      const value = Math.min(
        current[j - 1]! + 1,      // insercion
        previous[j]! + 1,          // borrado
        previous[j - 1]! + cost,   // sustitucion
      );
      current[j] = value;
      if (value < rowMin) rowMin = value;
    }
    if (rowMin > maxDistance) return maxDistance + 1;
    [previous, current] = [current, previous];
  }

  return previous[b.length]!;
}

/** Puntaje 0..1 de similitud entre dos textos ya normalizados. */
export function similarity(a: string, b: string): number {
  if (a === b) return 1;
  const longest = Math.max(a.length, b.length);
  if (longest === 0) return 1;
  return 1 - levenshtein(a, b) / longest;
}
